[Extremality of all Series--Sinai states, \cite{SS90}]
\label{conj:ss_conjecture}
    Let \(p,\,q\ge{3}\) such that \(1/p+1/q<1/2\).
    For \(\beta \in (0, \infty)\) large enough,
    \begin{equation}
        \mathrm{SS}_{\beta}(p,q)
        \subset
        \exG_\beta.
    \end{equation}

\label{conj:bgs}
Let $M=[v_0,\ldots,v_{2^{s-1}-1}]$ have nonzero columns and satisfy
$\sum_{i=0}^{2^{s-1}-1}v_i=0$.  Then $M$ has a Hadamard pair solution.

\label{cjy_conjecture}
Let $(X^n,\omega)$ be a connected, compact K\"ahler manifold and $\Omega\in \Homology^{1,1}(X,\Reals)$. Assume that $Z_X(\Omega)\ne 0$, $\mathcal{H}_{\Omega}$ is non-empty, and $\Omega$ is supercritical. Then, the following are equivalent 
\begin{enumerate} 
\item The dHYM equation admits a solution\label{exitsdHYMsol}.
\item For every proper subvariety $V\subset X$,\label{central>0}
\begin{equation}
		\Im \left( \frac{Z_V(\Omega)}{Z_X(\Omega)} \right)>0.
	\end{equation}		
\end{enumerate}

\label{conj-folklore}
Let $X$ and $Y$ be any Dynkin diagrams of ADET type. The Nahm sums associated with $(M(X,Y),0,C(X,Y))$ is modular where 
\begin{align}
M(X,Y)=\mathcal{C}(X)\otimes \mathcal{C}(Y)^{-1}, \quad C(X,Y)=-\frac{1}{24}\frac{r(X)r(Y)h(X)}{h(X)+h(Y)}.    
\end{align}    
Here $\otimes$ denotes the Kronecker product of matrices.

\label{conj:multi-layer-degree}
  Let $F\colon \R^n \to \R^m$ be a fully connected neural network classifier with $\ell$ hidden layers of widths $n_1,\ldots,n_\ell \geq n$, logistic sigmoid activation at each hidden layer, and a linear output layer. Assume that the weight matrices $A^{(1)},\ldots,A^{(\ell)}$ are rational with common denominator $q$ and in general position, and let $L=q\max_{k,i,j}|a_{ki}^{(j)}|$ be the lattice constant, where the $a_{ki}^{(j)}$ are the entries of the $j$-th layer's weight matrix. Then each pairwise decision boundary $V_{ij} = \mathcal{Z}(F_i-F_j)$, if bounded and smooth, satisfies
  \begin{equation}\label{eq:multi-layer-bound}
    \md(V_{ij}) \leq C(n,L)\cdot \left(\prod_{i=1}^\ell n_i\right)^n,
  \end{equation}
  where $C(n,L)$ depends only on $n$ and $L$.

\label{conj:block-khovanskii}
  Let $f\colon \R^n \to \R$ be the output of a fully connected neural network with $\ell$ hidden layers of widths $n_1, \ldots, n_\ell$ and a Pfaffian activation function $\sigma$ satisfying $\sigma' > 0$. Then the number of regular solutions of a Pfaffian system involving $f$ and its derivatives, of the form~\eqref{eq:pfaffian-system}, is bounded by
  \begin{equation*}
    2^{\frac{\ell(\ell-1)}{2} + \sum_{i=1}^{\ell}\frac{n_i(n_i-1)}{2}} \cdot p(\alpha, \beta, n, \ell, n_1, \ldots, n_\ell),
  \end{equation*}
  where $p$ is a polynomial in the indicated quantities.

Suppose that $1 < p < \infty$. Let $M$ be a Cartan-Hadamard manifold whose sectional curvature is bounded above by a strictly negative constant. Then
\begin{equation}
\label{Lohoue-improved}
\norm{\nabla f}_{\L^p(M,\mathrm{T}M)} 
\lesssim_{p,M} \bnorm{(-\Delta)^{\frac{1}{2}} f}_{\L^p(M)} ,\quad f \in \C^\infty_0(M).
\end{equation}

{bib:etzion1}}]
\label{con:etzsilb}
For every Ferrers diagram $\mathcal{F}$ of order $n$, every integer $1\leq{d}\leq n$ and every finite field $\mathbb{F}_q$ there exists an  $[\mathcal{F},{\nu_{\min}(\mathcal{F},d)},d]_q$ MFD code.

\cite{hafidh2019multiset}
Let $T$ be a tree. If $md(T) < \infty$, then $md(T) \le n - \operatorname{diam}(T) + 1$
and the bound is sharp.

\label{conj:interval}
Lemma~\ref{lem:interval} holds for every odd $m$; consequently
$\kmin(C_m)=m-1$ for every odd cycle.

\label{opnormconj}
     Let $\varepsilon > 0$. Then for any $A, B \geq 1$,
    \begin{equation} \label{Xistep}
        \Xi_4(A,B) \ll_{\varepsilon} (AB)^{\varepsilon}(A + B + A^{3/4} B^{1/2} + A^{1/2} B^{3/4}).
    \end{equation}

For any prime $p>3$, we have the congruences
\begin{equation} \sum_{n=1}^{p-1}\f{(-1)^n}{n}f_n\eq-\f {13}6 p^2B_{p-3}\pmod{p^3}
\end{equation}
and
\begin{equation} \sum_{n=1}^{p-1}\f{(-1)^n}{n^2}f_n\eq\f 76 pB_{p-3}\pmod{p^2},
\end{equation}
where $B_0,B_1,\ldots$ are the Bernoulli numbers.

\label{conj:indminors}
Let $H$ be a planar graph.
Then, for every fixed $r$ and \cmsotwo formula $\psi$, $(\tw \leq r,\psi)$-\MWIS and \lcol{3} can be solved in polynomial time in $H$-induced-minor-free graphs.

\label{conjecture}
    Let $\Lambda=kQ/I$ be a representation-finite bound path algebra of rank $n$.
    \begin{enumerate}
        \item We have $\MagnitudeOfModuleCat{\Lambda}\geq n$.
        \item We have $\MagnitudeOfModuleCat{\Lambda} = n$ if and only if $\Lambda$ is special biserial.
    \end{enumerate}

\label{conj:odd_cycles_basis}
Let $n,m\ge 3$. 
    A pair of graphs $(G,H)$ on $n$ and $m$ vertices resp. has the property that the rows of the Jacobian $\mathcal{H}(G,H)$ indexed by $E(G)\times E(H)$ form a basis to the row space of  $\mathcal{H}(K_n,K_m)$, equivalently $\ell(J_{G,H}) = |E(G)||E(H)| = |V(G)||V(H)|$, if and only if both $G$ and $H$ are disjoint unions of odd cycles.

\label{question-cycle}
    Let $n,m\geq 3$ be positive integers. 
    Then if $F$ has characteristic zero


    \begin{equation*}
        \ell(J_{C_n,C_m}) =
        \begin{cases}
            nm \text{ }& \text{ $n$ and $m$ are odd}\\
            nm - 1 & \text{ exactly one of $n$ or $m$ is even}\\
            nm-2 & \text{ $n$ and $m$ are even}.
        \end{cases}
    \end{equation*}
    This identity implies that $(C_n,C_m)$ is a basis if and only if $n$ and $m$ are odd.

\label{conj:71}
For $k\ge2$ and $k\equiv2,3\pmod4$,
$b_2(2k)=k+1$.

\label{conj:main}
For all $n\geq 0, i\geq 3, k\geq 0$, we have
\begin{align}
\overline{b}_{2^i k + 2^{i-1}-1}(8n+5) &\equiv 0 \pmod{2^{i+2}}, \label{conj:b_8n+5}\\
\overline{b}_{2^i k + 2^{i-1}-1}(8n+7) &\equiv 0 \pmod{2^{i+3}} \label{conj:b_8n+7}.
\end{align}

\label{feedback-exponent} [The Feedback-Exponent Conjecture]\label{conj}
    Let $k_0\geq 1$ be an integer. Then there exists a rational number 
$p/q\in[1,2]$ that cannot be realized as the Turán exponent of any bipartite graph whose minimum FVN is at most $k_0$.

\label{C-1}
If $8n +9$ has a prime divisor $p \equiv  5, 7 \pmod 8$ raised  to odd exponent,
 equivalently,  if $8n+9$ is not represented by  $x^2+2y^2$, 
 then
	\begin{align}\label{t-1}
 t_o(n) \equiv 0 \pmod 2. 
 \end{align}

\label{wildconjecture}
    There exists a function $f(k) \in \mathcal{O}(k \log k)$ such that every graph $G$ contains $k$ vertex-disjoint cycles with distinct lengths, or a set $X$ of at most $f(k)$ vertices such that $|\Lambda(G-X)|
    \leq k-1$.

\label{ssc_mnest_dih_conj}
    For any $a \ge 2$ and any even $b \ge 2$, we have
    \[
        R_\mathrm{dih}(S^\mathrm{sc}_a, M_b^\mathrm{nest}) = \begin{cases}
            a + b - 3, & \mbox{if $a$ is odd and $4 \mid b$},\\
            a + b - 2, & \mbox{otherwise}.
        \end{cases}
    \]

\label{thm-main}  Let $(X, L)$ be a smooth  polarized projective manifold which admits a cscK metric in $2\pi c_1(L)$ and $\poiss \in H^0(X, \Wedge^2 T^{1,0}_X)$ be a non-zero holomorphic Poisson tensor. Then the following are equivalent:

\begin{enumerate}
\item The bivector $\poiss$ is polystable for the linear action of $\Aut_{\rm red} (X)$ on $H^0(X, \Wedge^2 T^{1,0}_X)$;

\item There exists $\epsilon >0$ such that for $|\lambda|< \epsilon$, $(X, \lambda\poiss, 2\pi c_1(L))$ admits a cscGK structure.
\end{enumerate}

\label{conj:arithsw}
The generating series of arithmetic  special cycles of top degree is given by 
    \begin{align*}
        \widehat{\deg}\ \Theta_{n+1}^{\mathrm{arith}}(\tau,\varphi)&=\sum_{T\in\operatorname{Sym}_{n+1}(\QQ)}\widehat{\deg}\ (\widehat{Z}(T,v,\varphi))q^T\\
        &=C\cdot E'(\tau,0,\lambda_f(\varphi)\otimes \Phi_k),
    \end{align*}
    that is, the central derivative of a Siegel Eisenstein series of genus $r=n+1$ and weight $k$ associated with $\varphi$.

Here, $\tau=u+iv\in \HH_{n+1}$, and $C$ is a certain normalizing constant.

\label{Andrade&Keating Ratios Conjecture}\label{ratios}
		Suppose that the real parts of $\alpha_k$ and $\gamma_m$ are positive and that $q$ odd is the fixed cardinality of the finite field $\mathbb{F}_q$. Then we have

		\begin{equation*}
			\begin{split}
				\sum_{D\in\h}& \frac{\prod_{k=1}^KL\left(\tfrac{1}{2}+\alpha_k,\x_D\right)}{\prod_{m=1}^QL\left(\tfrac{1}{2}+\gamma_m,\x_D\right)}\\
				& =\sum_{D\in\h} \sum_{\varepsilon\in\{-1,1\}^K} |D|^{\frac{1}{2} \sum_{k=1}^K(\varepsilon_k-1)\alpha_k} \prod_{k=1}^{K} \xx\left(\tfrac{1}{2} +\tfrac{(1-\varepsilon_k)}{2}\alpha_k\right)\\
				&\ \ \ \times  Y_{D}(\varepsilon_1\alpha_1,\cdots,\varepsilon_K\alpha_K;\gamma) A_{D}(\varepsilon_1\alpha_1,\cdots,\varepsilon_K\alpha_K;\gamma)+o\left(|D|\right),
			\end{split}
		\end{equation*}
		where $\xx(s)=q^{-\frac{1}{2}+s}$ and $L(s,\chi_D)$ is the quadratic Dirichlet $L$-function associated to $D$, with $D$ being a monic and square-free polynomial in $\mathbb{F}_q[T]$,





		\begin{equation*}
			Y_D(\alpha;\gamma) = \frac{\underset{j\leqslant k\leqslant K}{\prod} \z(1+\alpha_j+\alpha_k) \underset{m<r \leqslant Q}{\prod} \z(1+\gamma_m+\gamma_r)} {\prod_{k=1}^K\prod_{m=1}^Q \z\left(1+\alpha_k+\gamma_r\right)},
		\end{equation*}
		and

		\begin{equation*}
			\begin{split}
				A_D(\alpha,\gamma) &= Y_D(\alpha;\gamma)^{-1}  \prod_{\substack{P \text{ monic}\\\text{irreducible}}}\left(1+\frac{1}{|P|}\right)^{-1} \\
				&\ \ \ \times  \left(\frac{1}{2} \frac{\prod_{q=1}^Q\left(1-\frac{1}{|P|^{\frac{1}{2}+\gamma_q}}\right)} {\prod_{k=1}^K\left(1-\frac{1}{|P|^{\frac{1}{2}+\alpha_k}}\right)}+ \frac{1}{2} \frac{\prod_{q=1}^Q\left(1+\frac{1}{|P|^{\frac{1}{2}+\gamma_q}}\right)} {\prod_{k=1}^K\left(1+\frac{1}{|P|^{\frac{1}{2}+\alpha_k}}\right)} +\frac{1}{|P|}\right),
			\end{split}
		\end{equation*}
		and $\zeta_{\mathbb{A}}(s)$ is the zeta-function associated to $\mathbb{F}_q[T]$.

\label{rationconjecture}
	 	Suppose that the real parts of $\alpha_k$ and $\gamma_m$ are positive and that $q\equiv 1 (\mod 4)$ is the fixed cordiality of the finite field $\mathbb{F}_q.$ Then we have,

	 	\begin{equation}
	 		\begin{split}
	 			\sum_{P\in\mathbb{P}_{2g+1}}& \frac{\prod_{k=1}^KL(\frac{1}{2}+\alpha_k,\x_P)}{\prod_{m=1}^QL(\frac{1}{2}+\gamma_m,\x_P)}\\
	 			& =\sum_{P\in\mathbb{P}_{2g+1}} \sum_{\varepsilon\in\{-1,1\}^K} |P|^{\frac{1}{2}\sum_{k=1}^K (\varepsilon_k-1)\alpha_k)} \prod_{k=1}^K \xx\left(\tfrac{1}{2}+\tfrac{\alpha_k-\varepsilon_k\alpha_k}{2}\right)\\
	 			& \ \ \	\times  Y_{\mathfrak{P}}(\varepsilon_1\alpha_1,\cdots,\varepsilon_K\alpha_K;\gamma)A_{\mathfrak{P}}(\varepsilon_1\alpha_1,\cdots,\varepsilon_K\alpha_K;\gamma)+o\left(|P|\right).\\
	 		\end{split}
	 	\end{equation}
	 	where

	 	\begin{equation*}
	 		Y_{\mathfrak{P}}(\alpha;\gamma):= \frac{\prod_{ j\leqslant k\leqslant K} \z(1+\alpha_j+\alpha_k)\prod_{ q<r\leqslant Q} \z(1+\gamma_r+\gamma_q)}{\prod_{k=1}^k\prod_{q=1}^Q \z(1+\alpha_k+\gamma_q)}.
	 	\end{equation*}
	 	and
	 	\begin{equation*}
	 		\begin{split}
	 			A_{\mathfrak{P}}(\alpha;\gamma)&= Y_{\mathfrak{P}}(\alpha;\gamma)^{-1}\\

	 			&\ \ \ \times \prod_{\substack{P \text{ monic}\\ \text{irreducible}}}  \frac{1}{2} \left(\frac{\prod_{q=1}^Q\left(1-\frac{1}{|P|^{\frac{1}{2}+\gamma_q}}\right)} {\prod_{k=1}^K\left(1-\frac{1}{|P|^{\frac{1}{2}+\alpha_k}}\right)}+\frac{\prod_{q=1}^Q\left(1+\frac{1}{|P|^{\frac{1}{2}+\gamma_q}}\right)} {\prod_{k=1}^K\left(1+\frac{1}{|P|^{\frac{1}{2}+\alpha_k}}\right)}\right).
	 		\end{split}
	 	\end{equation*}

\label{Our Ratios Conjecture2.}
		Let $A=\{\alpha_1,\cdots,\alpha_K\}$ and $B=\{\gamma_1\cdots,\gamma_Q\}$ such that $\alpha_k$ is such that, $1\leqslant k \leqslant K$, and $\gamma_m$ is such that, $1\leqslant m \leqslant Q$ satisfying the restrictions in (\ref{comditions}).
		Then

		\begin{equation}\label{df}
			\begin{split}
				R_{DL}(A,B)&=\sum_{D\in\h}  \frac{\prod_{k=1}^K L\left(\tfrac{1}{2}+\alpha_k,\x_D\right)}{\prod_{m=1}^Q L\left(\tfrac{1}{2}+\gamma_m,\x_D\right)}\\
				& = \sum_{D\in\h} \sum_{\D\subseteq A} \left|D\right|^{- \sum_{\delta\in \D}\delta } \prod_{\delta\in \D} \xx\left(\tfrac{1}{2}+\delta\right) Y_{DL}(A,B,\D) A_{DL}(A,B,\D)\\
				& \ \ \ + o\left(|D|\right),
			\end{split}
		\end{equation}
		where $Y_{DL}(A,B,\D),A_{DL}(A,B,\D)$ are defined as in equations (\ref{Y_{DL}}) and (\ref{A_{DL}}) respectively.

\label{open}
Let $A$ be an $F$-algebra (maybe infinite dimensional).
Then $A$ is zJpd if and only if it is zpd.

\label{conj-KZ}
There exist an isomorphism
$$\mathcal{Z}_{\mathcal{A}} \cong \mathcal{Z}/\zeta(2)\mathcal{Z}\ ;\ \zeta_{\mathcal{A}}(\mathds{k}) \mapsto \zeta_S(\mathds{k}).$$

\label{conj} \rm (See \cite[Conjecture~2.13]{JHL}.) Assume that the Hessenberg system $\Phi$ is circular. Then there exist scalars
 $\beta, \gamma, \gamma^*, \varrho, \varrho^*$  such that both
\begin{align}
0 &= \lbrack A, A^2 A^*-\beta A A^* A + A^* A^2 - \gamma(AA^*+A^* A) -\varrho A^* \rbrack,   \label{eq:CTD1} \\
0 &= \lbrack A^*, A^{*2} A-\beta A^* A A^* + A A^{*2} - \gamma^*(A^*A+A A^*) -\varrho^* A \rbrack. \label{eq:CTD2}
\end{align}

\cite{MR2928935}\label{main.conj.jk}
  Let $Y$ be a complex analytic manifold and \(f:Y\to \Delta\)  a
  projective morphism. Then the following are equivalent.
  \begin{enumerate}
  \item $f$ is smooth, hence a differentiable fiber bundle.
  \item $f$ is a homotopy fiber bundle.
  \item $f$ is a $\z$-homology fiber bundle.
  \end{enumerate}

\label{conj:G2}
For $d\ge5$ and every split $(a,b)$ with $a\le b$, the remainder $R_{(a,b)}$
has total degree at most $d-3$.

\label{conj:symplectic-p-curvature}
Let $M$ be a semipositive symplectic manifold. Let 
\[Q\Sigma_{\omega} = F^{\Grad^{QM}}_{x \partial x}. \]

\label{conj:main} A cutoff occurs as soon as 
		\begin{eqnarray}
			\label{def:PC}
			\gamma\times \tmix(\varepsilon) & \xrightarrow[n\to\infty]{} & +\infty,
		\end{eqnarray}
		for some $\varepsilon\in(0,1)$, where $\gamma$ denotes the Poincaré constant of the considered process.

Then for some absolute constants $C_1, C_2$ so that for 
    every simple algebraic group $G$ (over an algebraically closed field), we have 
    \[C_1\frac{\dim(G)}{\rank(G)} 
    \leq \packingNumber(G)
    \leq \frac{\dim(G)}{\rank(G)}
    \leq \coveringNumber(G)\leq C_2 \frac{\dim(G)}{\rank(G)}.\]

\label{conj1}
    We have $\Lambda\Sigma = \Delta$, where:
    \begin{itemize}    
        \item $\Lambda$ is the character of $\dih_{n+2}\times \mathfrak{S}_n$ acting on the reduced homology group $\tilde H_{n-2}(\CPF_n)$,
        \item $\Sigma$ is a sign character of $\dih_{n+2}$ extended to $\dih_{n+2}\times \mathfrak{S}_n$ (see Definition~\ref{def:sigma}),
        \item $\Delta$ is the character of $\dih_{n+2}\times \mathfrak{S}_n$ acting on diagonal coinvariants $A/I$.
    \end{itemize}

\label{conj2}
    For any $\FFF$ in $\dih_{n+2}$ and $\sigma\in\mathfrak{S}_n$, we have:
    \[
        (\Lambda\Sigma)(\FFF,\sigma) = \varDelta(\sigma)\Big\vert_{\substack{q=\lambda_1 \\ t=\lambda_2}}
    \]
    where $\lambda_1,\lambda_2$ are the eigenvalues of $\rho_1(\FFF) \in O(\mathbb{R}^2)$.

\label{conj:rotcox}
    Let $\FFF$ be a rotation (a power of $\RRR$), and $\mu$ a root of $1$ with the same order as $\FFF$.  We have:
    \begin{equation} \label{eq:charrot}
        \Lambda(\FFF,w)
            =
        (-1)^n \cdot (-h-1)^{\dim\ker(w-\mu 1_W)}.
    \end{equation}

Given coefficients $a,b,c\in\N$, the equation
    \begin{equation}\label{eq:genPyth}
        ax^2+by^2=cz^2
    \end{equation}
    is partition regular if and only if $c\in\{a,b,a+b\}$.

Let $n$ be a positive odd integer with $n\equiv 3\pmod{4}$. Then,
\begin{align*}
	\sum_{i=0}^{\frac{n-1}{2}}\sum_{j=0}^{\frac{n-1}{2}}\frac{(q;q^{2})_{i+j}(q;q^{2})_{i}(q;q^{2})_{j}(-q;q^{2})_{j}}{(q^2;q^2)_i^2(q^2;q^2)_j^2(-q^2;q^2)_j}q^{2i+2j}\equiv0\pmod{\Phi_{n}(q)^2}.
\end{align*}

\label{thm-ApaZeil-qcon}
	Let $n, r, s$ be positive integers. Then,  modulo $\Phi_{n}(q)^2$,
	\begin{align}\label{thm-ApaZeil-qcon-1}
		\sum_{i=0}^{rn-1}\sum_{j=0}^{sn-1}\frac{(q;q)_{i+j}^2}{(q;q)_i^2(q;q)_j^2}q^{i+j}\equiv\bigg(\frac{n}{3}\bigg)q^{2(n^2-1)/3}\sum_{i=0}^{r-1}\sum_{j=0}^{s-1}\frac{(q^{n^2};q^{n^2})_{i+j}^2}{(q^{n^2};q^{n^2})_i^2(q^{n^2};q^{n^2})_j^2}q^{n^2(i+j)}.
	\end{align}

\label{conj3}
    We have an equivalence of $\mathbb{E}_1$-algebras
    \begin{align*}
    \textnormal{add}(\textnormal{Conv}((\mathscr{P}^{\textnormal{!`}})^{\textnormal{cu}},\e_A)^{\phi}) \simeq \mathfrak{Z}(A) \in \alg_{\mathbb{E}_1}(\alg_{\mathscr{P}}(\dk)).
    \end{align*}

\label{intro_con_GHL}
The isomorphism \eqref{eq:intro_isoCompleted} restricts to an isomorphism
$$ \smash{K_0(\mathcal{O}_{sh}^{\Z})\simeq \AGHL.}$$

\label{intro_con_FH}
There are explicit simple objects $L_{w\varpi_i^{\vee},a}$ such that
\begin{equation*}
\smash{Q_{w\varpi_i^{\vee},a}=\chi_{\ell}(L_{w\varpi_i^{\vee},a}).}
\end{equation*}
In particular, the classes in $K_0(\mathcal{O}_{sh}^{\Z})$ of the $L_{w\varpi_i^{\vee},a}$'s satisfy the extended $QQ$-system \eqref{eq:intro_the_extended_QQ_system}.

\label{con:sec_qq_systems}
Choose  
$w\in W$ such that $\ell(ws_i)>\ell(w)$. Then $V_w=L_{w\varpi_i,a}\otimes L_{ws_i\varpi_i,a+2}$ is of highest $\ell$-weight and there is a non-split short exact sequence
\begin{equation}\label{eq:SECQQ}
\textstyle 0 \to L_{ws_i\varpi_i,a}\otimes L_{w\varpi_i,a+2} \to  V_w \to \bigotimes_{j\sim i} L_{w\varpi_j,a+1}\to  0
\end{equation}
that categorifies the extended QQ-system.

\label{Conj-Odd}
For any odd integer \(\ell \ge 3\) and sufficiently large \(n\), it holds that
$$p_\ell(2n+1)=n^2+n.$$

Let \(X:M^n\to\R^{n+1}\) be a complete self-shrinker.  If the squared norm \(S\)
of the second fundamental form is constant, then \(X(M)\) is isometric to one of
the following standard models:
\begin{enumerate}[label=\textnormal{(\arabic*)},leftmargin=2em,itemsep=2pt,topsep=2pt]
\item the hyperplane \(\R^n\);
\item a round cylinder \(\Sphere^k(\sqrt{k})\times\R^{n-k}\), \(1\leq k\leq n-1\);
\item the round sphere \(\Sphere^n(\sqrt n)\).
\end{enumerate}
Equivalently, constant \(S\) should force \(S\equiv0\) or \(S\equiv1\).

