\label{prop:gcf}
  The formal continued fraction of $g(N) = \sqrt{R_N/2}$ is
  \begin{equation}\label{eq:gcf}
    g(N) = \Bigl[0;\; 2N+1,\; 4N+2,\;
            \Bigl\lfloor\frac{12N+6}{19}\Bigr\rfloor,\; \ldots\Bigr]
  \end{equation}
  with quasi-polynomial partial quotients of periods $1, 1, 19, \ldots$
  In particular, at $N = N_k$:
  \begin{equation}\label{eq:gcf-pell}
    \PQ_1(g)\big|_{N_k} = 2N_k+1 = Q_{2k+1}, \qquad
    \PQ_2(g)\big|_{N_k} = 4N_k+2 = 2Q_{2k+1}.
  \end{equation}

{\it If $1\leq a<b<c<d$ are integers with $ad=bc$, then
$$\gauss{b+c}b \ \geq \ \gauss{a+d}a \, ,$$
where the inequality is understood coefficient-wise.}

If \(G\) is an extremal graph on \(n\geq 6\) vertices in the class of all graphs on \(n\) vertices, then $G\in \mathcal{G}$, where
\begin{eqnarray*}
\mathcal G &=&
\left\{ \frac{n}{3}C_3:
n\geq 6 \text{ and } n\equiv 0 \pmod 3 \right\} \cup \\
&& \left\{
\frac{n-4}{3}C_3 + C_4:
n\geq 7 \text{ and } n\equiv 1 \pmod 3 \right\} \cup \\
&& \left\{
\frac{n-8}{3}C_3 + 2C_4:
n\geq 8 \text{ and } n\equiv 2 \pmod 3 \right\}.
\end{eqnarray*}

\label{conj:gromov}
Let $\alpha \in (0,1)$ and let $k > n$. Every $\alpha$-H\"older continuous embedding
$F: \B^k \subset \R^k \to \mathbb{H}_n$ satisfies $\alpha \leq \frac{1}{2}$.

\label{conj:Rogers-Shephard-ineq-p-zonoids}
        For $p\ge 1$, let $Z \subset \R^n$ be an asymmetric $L_p$-zonoid. Then
        \begin{equation}\label{eq:Rogers-Shephard-ineq-p-zonoids-conj}
            |Z \oplus_p -Z| \leq 2^n\,|Z|.
        \end{equation}
        Moreover, if $p>1$, equality holds if and only if $Z$ is contained in a hyperplane or is the $L_p$-sum of $n$ segments with the origin as an endpoint, or equivalently, $Z$ is the image of $B_q^n\cap\R_+^n$ under a nonsingular linear transform, where $q$ satisfies $1/p+1/q=1$.

\label{conj:projection-cap-conj}
        Fix $q \ge 1$ and  $m\ge n \geq 1$. Then, for any $n$-dimensional subspace $E$ of $\mathbb{R}^m$, one has
        \begin{equation} \label{eq:projection-cap-conj}
            | P_E B_q^m|_n\leq 2^n|P_E(B_q^m \cap \mathbb{R}^m_+)|_n .
        \end{equation}
    Moreover, equality holds if and only if there exists a partition  $U_0, U_1, \dots, U_n $ of $[m]$ such that $U_j \neq \emptyset$ for every $ 1 \leq j \leq n$, $U_0 = \{ i\in [m] :P_E e_i = 0 \}$, and 

    for every $1\le j\le n$, there exist unit vectors $w_j\in\sum_{i\in U_j}\R_{>0} e_i$ such that $E=\textup{span}(w_1,\dots,w_n)$.

\label{conj:projection-cap-conj-uncon}
        Let  $m\ge n \geq 1$, let $E$ be an $n$-dimensional subspace of $\mathbb{R}^m$ and $K$ be an unconditional convex body in $\R^m$. Then 
        \begin{equation} \label{eq:projection-cap-conj-uncon}
            | P_E K|_n\leq 2^n|P_E(K \cap \mathbb{R}^m_+)|_n .

        \end{equation}

