\cite[Conjecture 12]{WhiteBases}\label{conj:white}
Let $\mathrm{M}$ be a matroid, and let $(B_1, \dotsc, B_s)$ and $(B_1', \dotsc, B_s')$ be sequences of bases of $\mathrm{M}$ such that the multiset union of $B_1, \dotsc, B_s$ is equal to the multiset union of $B_1', \dotsc, B_s'$. Then
\begin{enumerate}
\item \label{whitenc} It is possible to obtain $(B_1', \dotsc, B_s')$ from $(B_1, \dotsc, B_s)$ by repeatedly choosing two bases $B_i$ and $B_j$ with $i < j$, choosing a symmetric exchange $(\tilde{B}_i, \tilde{B}_j)$ of $(B_i, B_j)$, and replacing $(B_1, \dotsc, B_s)$ by $(B_1, \dotsc, B_{i-1}, \tilde{B}_i, \dotsc, B_{j-1}, \tilde{B}_j, \dotsc, B_s)$. 
\item \label{whitesymmetric} It is possible to obtain the multiset $\{B_1', \dotsc, B_s'\}$ from the multiset $\{B_1, \dotsc, B_s\}$ by repeatedly choosing two bases $B_i$ and $B_j$, choosing a symmetric exchange $(\tilde{B}_i, \tilde{B}_j)$, and replacing $\{B_1, \dotsc, B_s\}$ by $\{B_1, \dotsc, B_{i-1}, \tilde{B}_i, \dotsc, B_{j-1}, \tilde{B}_j, \dotsc, B_s\}$. 
\item \label{whitequadratic} It is possible to obtain the multiset $\{B_1', \dotsc, B_s'\}$ from the multiset $\{B_1, \dotsc, B_s\}$ by repeatedly choosing two bases $B_i$ and $B_j$, choosing any pair of bases $(\overline{B}_i, \overline{B}_j)$ with the property that the multiset union of $B_i$ and  $B_j$ is equal to the multiset union of $\overline{B}_i$ and $\overline{B}_j$, and replacing $\{B_1, \dotsc, B_s\}$ by the multiset $\{B_1, \dotsc, B_{i-1}, \overline{B}_i, \dotsc, B_{j-1}, \overline{B}_j, \dotsc, B_s\}$. 
\end{enumerate}

