\label{cnj:BH}
Let $f_1,\dots,f_k\in\Z[x]$ be distinct nonconstant irreducible polynomials with positive leading coefficients and $f$ their product. Let
$$\omega_{f}(p):=\big\vert\{ a\in \Z/p\Z : f(a)=0 \bmod p\}\big\vert$$
and assume $\omega_f(p)<p$ for every prime $p$. By denoting
\begin{equation} \label{e:cffBH} C(f):=\prod_{p\in\calp}\left(1-\frac{1}{p}\right)^{-k}\left(1-\frac{\omega_{f}(p)}{p}\right) \end{equation}
it follows
\begin{equation} \label{e:bhclssc}
\big|\bff^{-1}(\calp^k)\cap [0,r]\big|\;\approx\;\dfrac{C(f)}{\prod_{i=1}^k\deg(f_{i})}\int_2^r\dfrac{dt}{(\log(t))^k}
\end{equation}
where $\bff\colon\Z\rightarrow\Z^k$ is the map $a\mapsto(f_1(a),\dots,f_k(a))$, and $\approx$  denotes the same asymptotic behaviour as $r\to+\infty$.

\label{cnj:pBH} 
Let $f_1,\dots,f_k\in\Z[x]$ be distinct irreducible polynomials with positive leading coefficients and $\bff\colon\za\rightarrow\za^k$ the map $a\mapsto(f_1(a),\dots,f_k(a))$. Assume  $\bff\big(\za\big)\cap(\za^*)^k\neq\emptyset$. Then one has
\begin{equation} \label{e:prfBHZ}  \lim_{n\to 0}\widetilde\mu_{\bff^{-1}(\calp^k),n}=\mu_{\bff^{-1}((\za^*)^k)}\ . \end{equation}

\label{cnj:pBHD} Let $f_1,\dots,f_k\in D[x]$ be non-associate separable irreducible polynomials and denote their product by $\bff$. Assume $f(\da)\cap\da^*\neq\emptyset$. Then the following limits exist and the equalities hold:
\begin{equation} \label{e:pBHD} \lim_{\gotn\to 0}\mu_{\bff|_D^{-1}(\calp(D)^k),\gotn}=\mu_{\bff^{-1}((\da^*)^k)}\end{equation}

\begin{equation} \label{e:pBHDd} \lim_{\gotn\to 0}\mu_{\bff(D)\cap\calp(D)^k,\gotn}=\mu_{\bff(\da)\cap(\da^*)^k}\,.\end{equation}
We call \eqref{e:pBHDd} the {\em direct image}  profinite Bateman--Horn conjecture.

