Let the single-theater game have escalation set $S=\{1,\dots,m\}$.
\begin{enumerate}
\item[(1)] (Proved.) The single-theater mis\`ere game is solved exactly by
Theorem~\ref{thm:A}: the $\mathcal{P}$-positions are $r\equiv 1\pmod{m+1}$.
\item[(2)] (Conjecture.) For every $m$ the mis\`ere quotient of the
single-theater game is finite. Consequently multi-theater mis\`ere stability
is decidable: it is determined by the image of the joint state in a finite
commutative monoid.
\end{enumerate}

\label{conj:A2r}
For every fixed integer $r\ge 1$ and every fixed $\varepsilon>0$,
uniformly for $0<\eta\le 1/2$, one has
\begin{equation}
\label{eq:A2r}
    A_{2r}(n,\eta)
    \ll_{r,\varepsilon}
    n^{r+\varepsilon}+n^{2r+\varepsilon}\eta .
\end{equation}

\label{conj:D2r}
Let $r\ge 1$ be fixed, let $\delta>0$, and suppose that $H\ge n^{1/2+\delta}$. Put $M=H/\sqrt n$. Then, for every $\varepsilon>0$,
$$
    \mathcal{D}_{2r}(H,M;\omega) \ll_{r,\varepsilon,\delta} H M^r n^\varepsilon \Phi_r(\omega),
$$
uniformly for $1\le \omega\le n/10$, where the dependence on $n$ is suppressed in the notation. In the ideal case one expects
\begin{equation}
 \label{eq:ideal-Phi}
  \Phi_r(\omega)\ll n^\varepsilon.
\end{equation}

