Let $f_r=x^2+r$ with $r=1/c$ for $c\in \Zi\backslash\{0,-1\}$, and let $k_n$ denote the number of irreducible factors of $f_r^n(x)$. Then $f_r$ is eventually stable over $\Qi$ with constant $C(f_r,0)=4$:
\begin{enumerate}
\item If $c=\alpha^2$ with $1\pm i\alpha\in \Zi\backslash\Zi^2$ then $k_n=2$ for all $n\ge 1$.\label{itm:m2}
\item If $c\in \{\pm 8i, -16\}\subset \Zi^2$, then $k_1=k_2=2$, $k_n=3$ for all $n\ge 3$.\label{itm:8i}
\item If $c= (i\sigma^2-i)^2$ for $\pm \sigma \in \Zi\backslash\{3,5,56\}$ then $k_1=2$ and $k_n=3$ for all $n\ge 2$.\label{itm:neq3556}
\item If $c= (is^2 - i)^2$ for $\pm s\in\{3,5,56\}$ then $k_1=2$, $k_2 =3$ and $k_n=4$ for all $n\ge 3$. \label{itm:3556}
\item If $c\neq 48$ and $c=\alpha^2(2i-\alpha^2)$ for some $\alpha \in \Zi$, then $k_1 =1$ and $k_n=2$ for all $n\ge 2$.\label{itm:neq48}
\item If $c=48$, then $k_1=1, k_2=2$, and $k_n=3$ for all $n\ge 3$. \label{itm:48}
\item If $c\in \Zi\backslash\Zi^2$ and $c\neq \alpha^2(2i-\alpha^2)$ for any $\alpha \in \Zi$ (i.e. $c$ is not in an above case), then $k_n=1$ for all $n\ge 1$. \label{itm:irred}
\end{enumerate}

