\label{conj:pattern}
For all $k\geq2$ and $\ell\geq k+1$,
\begin{equation}\label{eq:pattern}
  \Delta_k(\ell) \;=\; A_k(\ell)\,(2\ell-3)!! \;-\; B_k(\ell)\,2^{\ell-k+1}\,\ell!,
\end{equation}
where $A_k(\ell)$ and $B_k(\ell)$ are polynomials in $\ell$ with rational
coefficients satisfying:
\begin{enumerate}[label=(\roman*),leftmargin=*]
