\label{con:Fin}
Fix $\mathbf n$ as above, and set $n_0=0$.
Consider a monotone (weakly) decreasing sequence of $n_k$ non-negative real numbers  $\left( \alpha_i \right)_{i=1}^{n_k}$ such that  $\alpha_{n_i}> \alpha_{n_i+1}$,  but $\alpha_j=\alpha_{j+1}$ otherwise. 
Let $u^{\infty}\in \mathrm{Toep}_{\infty}(\R_{\ge 0})$ be the infinite totally nonnegative Toeplitz matrix with generating function  
\begin{equation}\label{e:con1}
    p_{u^\infty }(x)=  \frac{1}{\prod\limits_{j=1}^{n_k}(1-\alpha_jx)} =\frac{1}{\prod\limits_{i=1}^{k}(1-\alpha_{n_i}x)^{n_i -n_{i-1}}}.
\end{equation}
Then there exists a sequence of matrices $u^{(n)}$, with $u^{(n)}\in X_{P_{\mathbf n}^{(n)}}(\R_{> 0})$, which converges to $u^{\infty}\in \mathrm{Toep}_{\infty}(\R_{\ge 0})$.
Conversely, every Toeplitz matrix $u^\infty$ with $p_{u^\infty}(x)$ as in \eqref{e:con1} arises as the limit of such a sequence.

\label{c:pflagconjectures-alt}
Suppose $(\mathbf n,\mathbf m)\in\mathcal S$ and recall the notations from above.
Consider a pair of infinite sequences  $\boldsymbol{\alpha}_{\mathbf{n}} \coloneq 
{\left(\alpha_i\right)}_{i\in \N}$ and $\boldsymbol{\beta}_{\mathbf{m}}\coloneq 
{\left( \beta_i \right)}_{i\in \N}$ in $\R_{\ge 0}$ satisfying the following conditions:
\begin{enumerate}
\item\label{item:1}  $\alpha_{n_i}> \alpha_{n_i+1}$ and $\beta_{m_i}> \beta_{m_i+1}$,
\item\label{item:2} $\alpha_j=\alpha_{j+1}$ (resp.\ $\beta_j = \beta_{j+1}$) for all $j\notin\{n_{1},n_2,\dotsc \}$ (resp.\ $j\notin  \{m_{1},m_2,\dotsc\}$),
 \item\label{item:4} $\sum \alpha_{i} <\infty$ and $\sum \beta_{i}<\infty$, 
  \item\label{item:3} If $\mathbf{n}$ (resp.\ $\mathbf{m}$) is finite of length $k$ (resp.\ $\ell$), then $\alpha_{j}=0$ for all $j>n_{k}$ and \ $\beta_{j}=0$ for all $j>m_{\ell}$.
  \end{enumerate}
  Define the infinite Toeplitz matrix $u^{\infty}\in \mathrm{Toep}_{\infty}(\R_{\ge 0})$ by its generating function \[
      p_{u^{\infty}}(x) = \frac{\prod\limits_{\beta\in \boldsymbol{\beta}_{\mathbf{m}}
        }(1 + \beta x)}{\prod\limits_{\alpha \in \boldsymbol{\alpha}_{\mathbf{n}}
        }(1-\alpha x)}.
    \]
Then there exists a sequence $(u^{(n)})_n$ with $u^{(n)}\in X_{P_{(\mathbf{n},\mathbf{m})}^{(n)}}(\R_{> 0})$ that converges to $u^{\infty}$.

\label{c:pflag-schub-lim}

  Given $(\mathbf n,\mathbf m)$ as above,  consider a pair of infinite sequences $\boldsymbol{\alpha}_{\mathbf{n}}$ and $\boldsymbol{\beta}_{\mathbf{m}}$ in $\R_{>0}$ satisfying the conditions (1)-(3) from Conjecture~\ref{c:pflagconjectures-alt}. Assume we have a sequence $(u^{(n)})_n$ with $u^{(n)}\in X_{P_{(\mathbf{n},\mathbf{m})}^{(n)}}(\R_{> 0})$ converging uniformly to $u^{\infty}$, where
   \[
      p_{u^{\infty}}(x) = \frac{\prod\limits_{\beta\in \boldsymbol{\beta}_{\mathbf{m}}
        }(1 + \beta x)}{\prod\limits_{\alpha \in \boldsymbol{\alpha}_{\mathbf{n}}
        }(1-\alpha x)}=\frac{\prod\limits_{j=1}^\infty(1+\beta_i x)}{\prod\limits_{i=1}^\infty(1-\alpha_j x)},
    \]
with the Schoenberg parameters given by $\boldsymbol{\alpha}_{\mathbf{n}}$ and $\boldsymbol{\beta}_{\mathbf{m}}$. Given a permutation $w\in W^{P_{\mathbf{m}}}$, 
  we have the following limit formula,
  \begin{equation} \label{eq:schub-lim-pflag}
    \lim\limits_{n\to \infty}{\left( \mathfrak{S}^{\hat w_n}_{(n)}(u^{(n)}) \right)}_n = S_w\left( \frac{1}{\beta_1},\frac{1}{\beta_2},\frac{1}{\beta_3}, \dots \right).        \end{equation}
 If $w\in W^{P_{\mathbf{n}}}$, then we have the limit formula 
 \begin{equation}\label{eq:schub-lim-pflag2}
     \lim\limits_{n\to \infty}{\left( \mathfrak{S}^{w}_{(n)}(u^{(n)}) \right)}_n = S_w\left( \frac{1}{\alpha_1},\frac{1}{\alpha_2}, \frac{1}{\alpha_3},\dots \right) .
 \end{equation}

\label{c:pflag-q-lim}
Let $(\mathbf n,\mathbf m)$ be as in Definition~\ref{d:infiniteflagseqs}. Consider a pair of sequences $\boldsymbol{\alpha}_{\mathbf{n}}$ and $\boldsymbol{\beta}_{\mathbf{m}}$ as in Conjecture~\ref{c:pflagconjectures-alt}, and suppose we have a sequence $u^{(n)}\in X_{P_{(\mathbf{n},\mathbf{m})}^{(n)}}(\R_{> 0})$ converging as in Proposition~\ref{p:pflag-q-lim-inf} to $u^{\infty}$, with Schoenberg parameters given by $\boldsymbol{\alpha}_{\mathbf{n}}$ and $\boldsymbol{\beta}_{\mathbf{m}}$. If $\mathbf{n}$ is finite of length $k$, then 
\begin{equation}\label{e:qinfnfin}
  \lim\limits_{n\to \infty} \sqrt[n]{q_{n_{i}}^{(n)}(u^{(n)})} = \begin{cases}
      \frac{\alpha_{n_{i+1}}}{\alpha_{n_{i}}} & i\leq k-1, \\
      \frac{1}{\alpha_{n_{i}}} & i = k .\\
  \end{cases}
  \end{equation}
Similarly, if $\mathbf{m}$ is finite of length $\ell$, then
  \begin{equation}\label{e:qinfmfin}
      \lim\limits_{n\to \infty} \sqrt[n]{q_{n-m_{i}}^{(n)}(u^{(n)})} = \begin{cases}
          \frac{\beta_{m_{i+1}}}{\beta_{m_{i}}}, & i\leq \ell-1 \\
           \frac{1}{\beta_{m_{i}}} & i=\ell. 
      \end{cases} 
  \end{equation}

