\label{con:Moss}
Fix an integer $k\geq 1$. For all sufficiently large $n$, there exists a family $\cF\subseteq \binom{[2n]}{n}$ such that:

\begin{enumerate}
    \item[(i)] $\cF$ has maximum possible size subject to containing no complementary pair; that is,
    \[
    |\cF|=\frac{1}{2}\binom{2n}{n}.
    \]
    \item[(ii)] $\cF$ contains no balanced subfamily of size $2,4,\ldots,2k$.
    \item[(iii)] $\cF$ contains a balanced subfamily of size $2k+2$.
\end{enumerate}

There exists a universal constant $C$, such that for any choice of $n$ symmetric matrices $(A_{i})_{i=1}^n \in \mathbb R^{n\times n}$ satisfying $\|A_i\|_{\op}\le 1$ there is a coloring $x\in\{\pm1\}^{n}$, such that
\begin{equation}
    \label{eq:1}
 \Bigl\|\sum\nolimits_{i=1}^n x_i A_i\Bigr\|_{\op} \le C \sqrt{n}.
\end{equation}

\label{conj:var}
 There exists a universal constant $C$, such that for any choice of $n$ symmetric matrices $A_{1}, \dots, A_{n} \in \mathbb R^{n\times n}$ satisfying $\|A_i\|_{\op}\le 1$ there exists a coloring $x\in\{\pm1\}^{n}$, such that
\begin{equation}
\label{eq:2}
\Bigl\|\nlsum_{i=1}^n x_i A_i\Bigr\|_{\op} \le C \Bigl\|\nlsum_{i=1}^n A_i^2\Bigr\|_{\op}^{1/2}.
\end{equation}

