\label{c:elliptic} Let $\mathbf{M}$ be a connected reductive $F$-split group, and let $M = \bM(F)$. Consider the following diagram:
  \begin{displaymath}\xymatrix@+1pc{
    {\Ress(M)_{\Psi(M)}} \ar[r]^{\FT_{\ess}^\vee} \ar[d]_{\res_{\cpt,\un}}
    & {\Ress(M)_{\Psi(M)}}\ar[d]^{\res_{\cpt,\un}}\\
    {  \cC(M)_{\cpt,\un}} \ar[r]_{\mathrm{FT_{\cpt,\un}}}
    & {  \cC(M)_{\cpt,\un}} }          
\end{displaymath} 
For every  unipotent element $u\in M^\vee$, essentially $M^\vee$-elliptic pair $(s,h) \in \cY(\Gamma_u)_{M^\vee-\ess}$, and maximal compact open subgroup $K$ of $M$, there exists a root of unity $\zeta=\zeta(u,s,h,K)$ such that
\[\res_K (\Pi^M(u,h,s))=\zeta \cdot (\FT_{\cpt,\un}\circ \res_K)(\Pi^M(u,s,h)). \]

\label{c:compact} Let $G$ be a connected reductive $F$-split group. The following diagram commutes up to roots of unity:
 \begin{displaymath}\label{e:diagram-cpt}
  \xymatrix@+1pc{
    {\Rcpt(G)} \ar[r]^{\mathrm{FT}^\vee_{\cpt}} \ar[d]_{\res_{\cpt,\un}}
    & {\Rcpt(G)}\ar[d]^{\res_{\cpt,\un}}\\
    {  \cC(G)_{\cpt,\un}} \ar[r]_{\mathrm{FT_{\cpt,\un}}}
    & {  \cC(G)_{\cpt,\un}} }          
\end{displaymath}
In other words, for each  unipotent element $u\in G^\vee$, compact pair $(s,h) \in \cY(\Gamma_u)/_\sim$, and maximal compact open subgroup $K$ of $G$, there exists a root of unity $\zeta=\zeta(u,s,h,K)$ such that
\[\res_K (\Pi(u,h,s)_c)=\zeta \cdot (\FT_{\cpt,\un}\circ \res_K)(\Pi(u,s,h)_c).
 \]

