\label{Conjecture1}
For every integers $k\geq1$ and $n\geq2$, we have
\begin{equation*}
\big(\varphi^k(n)+\psi^k(n)+\sigma^k(n)\big)\left(\frac{1}{\varphi^k(n)}+\frac{1}{\psi^k(n)}+\frac{1}{\sigma^k(n)}\right)\geq\frac{5(n^2-1)^k+2(n+1)^{2k}+2(n-1)^{2k}}{(n^2-1)^k}\,. 
\end{equation*}

\label{Conjecture2}
For every integers $k\geq1$ and $n\geq2$, we have
\begin{align*}
&\big((\varphi(n)+\psi(n))^k +(\varphi(n)+\sigma(n))^k+(\psi(n)+\sigma(n))^k\big)\\
&\times\left(\frac{1}{(\varphi(n)+\psi(n))^k}+\frac{1}{(\varphi(n)+\sigma(n))^k}+\frac{1}{(\psi(n)+\sigma(n))^k}\right)\\ 
&\geq\frac{5n^k(n+1)^k+2(n+1)^{2k}+2n^{2k}}{n^k(n+1)^k}\,.
\end{align*}

\label{Conjecture3}
For every integers $k\geq1$ and $n\geq2$, we have
\begin{equation*}
\frac{\varphi^k(n)}{\psi^k(n)+\sigma^k(n)}+\frac{\psi^k(n)}{\varphi^k(n)+\sigma^k(n)}+\frac{\sigma^k(n)}{\varphi^k(n)+\psi^k(n)}\geq\frac{4(n+1)^{2k}+(n^2-1)^k+(n-1)^{2k}}{2\big((n+1)^{2k}+(n^2-1)^k\big)}\,. 
\end{equation*}

\label{Conjecture4}
For every integers $k\geq1$ and $n\geq2$, we have
\begin{align*}
&\Big(\varphi^k(n)\big(\psi(n)+\sigma(n)\big)+\psi^k(n)\big(\varphi(n)+\sigma(n)\big)+\sigma^k(n)\big(\varphi(n)+\psi(n)\big)\Big)\\
&\times\left(\frac{1}{\varphi^k(n)\big(\psi(n)+\sigma(n)\big)}+\frac{1}{\psi^k(n)\big(\varphi(n)+\sigma(n)\big)}+\frac{1}{\sigma^k(n)\big(\varphi(n)+\psi(n)\big)}\right)\\
&\geq\frac{5n(n+1)^{k-1}(n-1)^k+2(n-1)^{2k}+2n^2(n+1)^{2k-2}}{n(n+1)^{k-1}(n-1)^k}\,. 
\end{align*}

\label{Conjecture5}
For every integers $k\geq1$ and $n\geq2$, we have
\begin{align*}
&\Big(\varphi^k(n)\big(\psi^k(n)+\sigma^k(n)\big)+\psi^k(n)\big(\varphi^k(n)+\sigma^k(n)\big)+\sigma^k(n)\big(\varphi^k(n)+\psi^k(n)\big)\Big)\\
&\times\left(\frac{1}{\varphi^k(n)\big(\psi^k(n)+\sigma^k(n)\big)}+\frac{1}{\psi^k(n)\big(\varphi^k(n)+\sigma^k(n)\big)}+\frac{1}{\sigma^k(n)\big(\varphi^k(n)+\psi^k(n)\big)}\right)\\
&\geq\frac{10(n-1)^{2k}+7(n^2-1)^k+(n+1)^{2k}}{(n-1)^{2k}+(n^2-1)^k}\,. 
\end{align*}

\label{Conjecture6}
For every integers $k\geq1$ and $n\geq2$, we have
\begin{align*}
&\frac{\varphi^k(n)\psi^k(n)}{\sigma^k(n)\big(\varphi^k(n)+\psi^k(n)\big)}+\frac{\varphi^k(n)\sigma^k(n)}{\psi^k(n)\big(\varphi^k(n)+\sigma^k(n)\big)}+\frac{\psi^k(n)\sigma^k(n)}{\varphi^k(n)\big(\psi^k(n)+\sigma^k(n)\big)}\\
&\geq\frac{4(n-1)^{2k}+(n^2-1)^k+(n+1)^{2k}}{2\big((n-1)^{2k}+(n^2-1)^k\big)}\,. 
\end{align*}

\label{Conjecture7}
For every integers $k\geq1$ and $n\geq2$, we have
\begin{align*}
&\frac{\big(\varphi(n)+\psi(n)\big)^k}{\big(\varphi(n)+\sigma(n)\big)^k+\big(\psi(n)+\sigma(n)\big)^k}+\frac{\big(\varphi(n)+\sigma(n)\big)^k}{\big(\varphi(n)+\psi(n)\big)^k+\big(\psi(n)+\sigma(n)\big)^k}\\
&+\frac{\big(\psi(n)+\sigma(n)\big)^k}{\big(\varphi(n)+\psi(n)\big)^k+\big(\varphi(n)+\sigma(n)\big)^k}\geq\frac{4n^{2k}+(n+1)^{2k}+n^k(n+1)^k}{2\big(n^{2k}+n^k(n+1)^k\big)}\,. 
\end{align*}

\label{Conjecture8}
For every integers $k\geq1$ and $n\geq2$, we have
\begin{align*}
&\frac{\varphi^k(n)\big(\psi(n)+\sigma(n)\big)}{\psi^k(n)\big(\varphi(n)+\sigma(n)\big)+\sigma^k(n)\big(\varphi(n)+\psi(n)\big)}
+\frac{\psi^k(n)\big(\varphi(n)+\sigma(n)\big)}{\varphi^k(n)\big(\psi(n)+\sigma(n)\big)+\sigma^k(n)\big(\varphi(n)+\psi(n)\big)}\\
&+\frac{\sigma^k(n)\big(\varphi(n)+\psi(n)\big)}{\varphi^k(n)\big(\psi(n)+\sigma(n)\big)+\psi^k(n)\big(\varphi(n)+\sigma(n)\big)}\\
&\geq\frac{n(n+1)^{k-1}(n-1)^k+(n-1)^{2k}+4n^2(n+1)^{2k-2}}{2n^2(n+1)^{2k-2}+2n(n+1)^{k-1}(n-1)^k}\,.
\end{align*}

\label{Conjecture9}
For every integers $k\geq1$ and $n\geq2$, we have
\begin{align*}
&\frac{\varphi^k(n)\big(\psi^k(n)+\sigma^k(n)\big)}{\psi^k(n)\big(\varphi^k(n)+\sigma^k(n)\big)+\sigma^k(n)\big(\varphi^k(n)+\psi^k(n)\big)}\\
&+\frac{\psi^k(n)\big(\varphi^k(n)+\sigma^k(n)\big)}{\varphi^k(n)\big(\psi^k(n)+\sigma^k(n)\big)+\sigma^k(n)\big(\varphi^k(n)+\psi^k(n)\big)}\\
&+\frac{\sigma^k(n)\big(\varphi^k(n)+\psi^k(n)\big)}{\varphi^k(n)\big(\psi^k(n)+\sigma^k(n)\big)+\psi^k(n)\big(\varphi^k(n)+\sigma^k(n)\big)}\\
&\geq\frac{5(n-1)^{2k}+5(n^2-1)^k+2(n+1)^{2k}}{\big(3(n-1)^k+(n+1)^k\big)\big((n-1)^k+(n+1)^k\big)}\,. 
\end{align*}

Let $\Sigma\subset \R^d$ be a compact set which is not a removable set for $\Delta$ in $L^2(\R^d)$. Then, there exist a self-adjoint extension  of $\Delta|_{C_c^\infty(\R^d\backslash \Sigma)}$ in $L^2(\R^d)$, $\widetilde{\Delta}$, and  a measure valued process $\left\{\mathcal{X}_t\right\}_{t\geq 0}$ such that  \begin{align*}
