\end{align*}
for any $t>0$ and any $x\in \R^3\backslash\Sigma$, where $\widetilde{u}$ is the solution to \begin{align*}
\partial_t u=\frac{1}{2}\widetilde{\Delta}u,\quad u(0,x)=u_0(x).
\end{align*}

