let the random variables $\vE^*$, $\vB^*$, $\vX_1$, and $\vX_2$ be independent with distributions
\begin{equation*}
    \vE^* \sim \Po(r^*), \qquad \vB^* \sim \Po(\alpha r^*), \qquad \vX_1, \vX_2 \sim \Po((1-\alpha)r^*).
\end{equation*}
Define the maximum of $\vX_1$ and $\vX_2$ to be $\vM^* = \max\{\vX_1, \vX_2\}$. Let the probabilities $q(r^*)$ and $p(r^*,\alpha)$ be given by
\begin{equation*}
    q(r^*) = \Pr(\vE^* \leq t-1) \quad \text{and} \quad p(r^*,\alpha) = \Pr(\vB^* + \vM^* \leq t-1).
\end{equation*}
Then, for all $c>c_{\mathrm{inf}}^{\mathrm{TGT}}$, the function
\begin{align}
    \alpha \mapsto 1 - \alpha + c \bc{q(r^*) \log\bcfr{p(\alpha)}{q(r^*)} + (1-q(r^*)) \log\bcfr{1-2q(^*)+p(r^*,\alpha)}{1-q(r^*)}} 
\end{align}
is maximised in $\alpha=0$.

\label{conj:NW}
Let $G$ be a $K_3$-divisible graph with $n$ vertices and
minimum degree $\delta (G) \geq \frac{3}{4}n$. If $n$ is sufficiently large, then $G$ admits a $K_3$-decomposition.

\label{conj:FracNW}
If $G$ is a graph on $n$ vertices with
minimum degree $\delta (G) \geq \frac{3}{4}n$, then $G$ admits a fractional $K_3$-decomposition.

\label{conj:fracNW2}
If $(G,\phi)$ is a triangle-covered edge-weighted graph on $n$ vertices with
$\delta(G) \geq \frac{3}{4}n$, then $|\phi|\ge 0$.

\label{conj:fracNW3}
If $(G,\phi)$ is a nonzero untied triangle-covered edge-weighted graph on $n$ vertices with
$\delta(G) \geq \frac{3}{4}n$, then $|\phi|\ge 0$.

\label{conj:FracNW4}
If $(G,\phi)$ is a nonzero untied triangle-covered edge-weighted graph on $n$ vertices with
$\delta(G) \geq \frac{3}{4}n$ and $f$ is a negative edge of $G$, then $\textrm{ch}_F(f)\ge 0$.

\label{conj:FracNW6}
If $(G,\phi)$ is a nonzero untied triangle-covered edge-weighted graph on $n$ vertices with $\delta(G) \geq \frac{3}{4}n$ and $f$ is a negative edge of $G$, then 
$$\textrm{ch}_F''(f)\le |\phi(f)|\cdot \frac{n^2}{4} \cdot \left(\frac{3}{n}\cdot |N(u)\cap N(v)| - 1 \right).$$

