	Let \. $\fa,\fb,\fc,\fd:\cP^\ell \to \rr_{\geq 0}$ \. be functions with finite support,
satisfying \eqref{eq:HKS-cond}.  Then we have:
\begin{equation}\label{eq:KLS}\tag{KLS}
\bigg( \sum_{\lambda \in \cP^\ell} \fa({\lambda}) \fs_\lambda\bigg)
	\bigg( \sum_{\lambda \in \cP^\ell} \fb({\lambda}) \fs_{\lambda} \bigg)
	\ \leqslant_{\fs} \
	\bigg( \sum_{\lambda \in \cP^\ell} \fc({\lambda}) \fs_\lambda \bigg)
	\bigg( \sum_{\lambda \in \cP^\ell} \fd({\lambda}) \fs_\lambda\bigg).
\end{equation}

\label{conj:SLC}
	For  all  \. $\lambda \in \rr^{\infty}_{\geq 0}$, $\zb \in \rr_{\geq 0}^\infty$ \. with finite support and any  $i\geq 1$,
	\begin{equation}\label{eq:SLC}\tag{SLC}
		\big(\partial^{\lambda+2\eb_i}\mathfrak{S}(\zb)\big) \.  \big( \partial^{\lambda} \mathfrak{S}(\zb) \big) \ \leqslant_{\fs} \  \big(\partial^{\lambda+\eb_i} \mathfrak{S}(\zb)\big)^2.
	\end{equation}

\label{conj:lowdegree}
Let $\mathbb{Q}_n$ denote the null hypothesis \eqref{null} and $\mathbb{P}_n$ denote the alternative \eqref{alt}.  
Denote $\bm{X} = \{ \bm{A}^{(l)}\}_{l=1}^{L}$.  If there exists $\eps \geq 0$ and $D \geq \log(nL)^{1+\eps}$ such that $\| L^{\leq D}_n(\bm{X}) \|^2 = 1 + o(1)$ then there is no polynomial-time test $\phi_n: \mathbb{R}^{L \times n \times n} \mapsto \{0,1\}$ such that the sum of Type I error and Type II error probabilities satisfy 
    \begin{align*}
        \mathbb{E}_{\mathbb{Q}_n}[ \phi_n(\bm{X})] + \mathbb{E}_{\mathbb{P}_n}[ 1 - \phi_n(\bm{X})] \to 0
    \end{align*}
    as $n \to \infty$.

\label{conj:period-obstruction}
Let $\Gamma$ be a smooth algebraic oval and let $\gamma$ be its lift to the normalization $X$ of the relevant irreducible Schwarz component.  If $\gamma$ is separating, then the exterior Cauchy transform is algebraic.  If $\gamma$ is nonseparating, then the exterior Cauchy transform is expected to be generically non-algebraic; in this conjectural picture algebraicity can occur only when the Abelian-period component of
\[
 \frac{1}{2\pi i}\int_\gamma\frac{\eta\,d\pi}{z-\pi}
\]
vanishes identically or cancels with the residue terms in an exceptional way.

\label{conjecture-2}
There is a fixed $\delta>0$ such that the inequality
$$
\#\big\{p\le x: p, p+h\in \mathbb{P}\big\}\gg_\delta \frac{x}{(\log x)^2}
$$
holds uniformly for any even $h\le x^\delta$, provided that $x$ is sufficiently large.

\cite[Conjecture 5.12]{amanba26}\label{AAB-conj-I}
Let $a$ be a positive integer. Then, for each positive integer $N$, we have
\begin{align*}
[q^{N2^a}]\sum_{m,n\geq 1}\frac{q^{mn2^a}}{(1+q^{n2^{a-1}})(1-q^{2m-1})}=\sigma_1(N),
\end{align*}
where $\sigma_1(n)$ is the sum of divisors of $n$.

For any word $\underline{w}$, the frayed weave consisting only of fraying vertices
		\begin{align*}
			\mathfrak{w}_{\mathrm{rev}}:(i_1,i_2,\dots,i_{\ell-1},i_\ell) &\to (i_1,i_2,\dots,i_{\ell-1},-i_\ell) \to (i_1,i_2,\dots,-i_{\ell-1},-i_\ell),\\
			&\to \cdots \to (i_1,-i_2,\dots,-i_{\ell-1},-i_\ell)\to (i_1,-i_2,\dots,-i_{\ell-1},-i_\ell),
		\end{align*}
		corresponding to the reversed opening sequence $(\ell, \ell-1,\dots,2,1)$ has its moduli of flags $M(\mathfrak{w}_{\mathrm{rev}})$ equal to the the intersection of all cluster tori in $\cO^{\underline{w}}$ reached along the maximal green sequence $\overrightarrow{\mu_{\underline{w}}}$ applied to $\seed(\underline{w})$.

\label{conj:wfss}
Let $F$ be a local field of characteristic zero and $G$ be a classical group over $F$. For any $\pi\in\Pi_F(G)$ with a generic local $L$-parameter, the following identities hold:
\begin{align}\label{s-max}
    \wf_\tr(\pi)^{s-\mx}=\wf_\ari(\pi)^{s-\mx}=\wf_\wm(\pi)^{s-\mx},
\end{align}
where $\wf_\square(\pi)^{s-\mx}$ denotes the subset of all maximal members in the wavefront set $\wf_\square(\pi)$ under the $F$-stable topological order over $\CN_F(\Fg)_\circ$
given in Definition \ref{defn:order}. Moreover, the following (stronger) identities also hold:
\begin{align}\label{r-max}
    \wf_\tr(\pi)^{r-\mx}=\wf_\ari(\pi)^{r-\mx}=\wf_\wm(\pi)^{r-\mx},
\end{align}
where $\wf_\square(\pi)^{r-\mx}$ denotes the subset of all maximal members in the wavefront set $\wf_\square(\pi)$ under the $F$-rational topological order over $\CN_F(\Fg)_\circ$.

\label{conj:DDW}
Let $F$ be a local field of characteristic zero and $G$ be a classical group over $F$. For any $\pi\in\Pi_F(G)$ with a generic local $L$-parameter, the following identities hold:
\begin{align*}              
    \wf_\des(\pi)^{s-\mx}=\wf_\wm(\pi)^{s-\mx} \quad {\rm and}\quad \wf_\des(\pi)^{r-\mx}=\wf_\wm(\pi)^{r-\mx},
\end{align*}
where the notations take the same meaning as in Conjecture \ref{conj:wfss}.

