according to 
\begin{equation} \label{g-conj}
\delta^g\mathrm{\tilde{C}}_t=-\tfrac{1}{2}(1+\mathrm{\tilde{C}}_t)\di \ln \det(1+\mathrm{\tilde{C}}_t)+\grad_g \varphi_t
\end{equation}
for a time dependent family of smooth functions $\varphi_t$ on $M$
\item[(ii)] assuming that the Cayley transform $\mathrm{C}_t$ of $g_t$ is normalised as  in (i) we must have
$$ \mathrm{C}_t \in \Gamma \left (\Sym^{2,-}TM \right )\ \mathrm{and} \ \bdel \mathrm{C}_t=[\mathrm{C}_t,\mathrm{C}_t]^c
$$
as well as the divergence equation $\delta^g\mathrm{C}_t=-\tfrac{1}{2}(1+\mathrm{C}_t)\di \ln \det(1+\mathrm{C}_t)$
\item[(iii)] the almost complex structure given by $J_t=(1-\mathrm{C}_t)^{-1}J (1-\mathrm{C}_t)$ is integrable, thus $(g_t,J_t)$ is a family K\"ahler-Einstein structures on $M$ with constant K\"ahler form $\omega$.
\end{itemize}

