    $$\hat{r}\left(\bigsqcup_{i= 1}^{s} K_{1, n_{i}}, \bigsqcup_{j= 1}^{t} K_{1, m_{j}}\right)= \sum_{k= 2}^{s+ t} \ell_{k}.$$

\label{conj1.4}
    For a given integer $t$, let $a_{1}, a_{2}, \dots, a_{t}$ be positive integers and let $a= \sum_{s= 1}^{t} a_{s}$. Moreover, let $n_{1}^{s}\geq n_{2}^{s}\geq \cdots\geq n_{a_{s}}^{s}\geq 1$ be integers for each $s\in [t]$. Let $\ell_{k}= \max\left\{\sum_{s= 1}^{t} n^{s}_{i_{s}}- t+ 1: \sum_{s= 1}^{t} i_{s}= k\right\}$ for each $k\in [a]\backslash [t- 1]$. Then
    $$\hat{r}\left(\bigsqcup_{i= 1}^{a_{1}} K_{1, n^{1}_{i}}, \bigsqcup_{i= 1}^{a_{2}} K_{1, n^{2}_{i}}, \dots, \bigsqcup_{i= 1}^{a_{t}} K_{1, n^{t}_{i}}\right)= \sum_{k= t}^{a} \ell_{k}.$$

Let $p$ be an odd prime, $Q_{p,d}=\mathbb{F}_p[[x_1,\ldots,x_d]]/(x_1^2+\ldots+x_d^2)$\footnote{note that here the index $d$ is shifted by 1 compared with other references like \cite{WYconj05} and \cite{PSSY}. The term $A_{p,d}$ in these references refer to $Q_{p,d+1}$.}, which is a singular ring of characteristic $p$ and dimension $d-1$. Then:
\begin{enumerate}
\item for any formally unmixed non-regular local ring $R$ of characteristic $p$ and dimension $d$, $e_{HK}(R)\geq e_{HK}(Q_{p,d+1})$.
\item $e_{HK}(Q_{p,d})\geq \lim_{p \to \infty}e_{HK}(Q_{p,d})$.
\item for any formally unmixed non-regular local ring $R$ of characteristic $p$ and dimension $d$, $e_{HK}(R)=e_{HK}(Q_{p,d+1})$ if and only if $R$ and $Q_{p,d+1}$ are isomorphic up to completion and change of base field.
\end{enumerate}

\label{NorineConj}
    Let \(Q_n\) be an \(n\)-dimensional hypercube. Then:
    \begin{enumerate}
        \item (Norine~\cite{Norine}) In any antipodal \(2\)-edge-colouring, there exists a monochromatic path connecting some vertex to its antipode.
        \item In any antipodal \(2\)-edge-colouring, there exists a monochromatic geodesic connecting some vertex to its antipode.
        \item (Feder--Subi~\cite{FederSubi}) In any \(2\)-edge-colouring, there exists a path connecting some vertex to its antipode with at most one colour switch.
        \item (Leader--Long~\cite{LeaderLong}) In any \(2\)-edge-colouring, there exists a geodesic connecting some vertex to its antipode with at most one colour switch.
     \end{enumerate}

Let $S$ be a set of groups (considered up to isomorphism) with trivial Frattini subgroup. Then, the following are equivalent:
    \begin{enumerate}
        \item There exists a finite structure $\structA$ such that $\ppchar(\structA)=S$.
        \item The set $S$ is closed under epimorphisms. Moreover,
        \begin{itemize}
            \item $S$ contains all groups (with trivial Frattini subgroup) or
            \item there is a finite set of primes $P$ such that $S$ contains all $p$-groups for all $p\in P$ and only finitely many other elements.
        \end{itemize}
    \end{enumerate}

