\label{conj:dist}
Assume that the edge weights $\wt\in\Rtpgauge$ are generic and let $\Hknk$ be given by~\eqref{eq:LPUNC:primitive_knk}. For $\ff,\f\in\Faces$, let $\distrk(\ff,\f):=\rank(\Hknk(\ff)-\Hknk(\f))$. 
Let $\distsep(\ff,\f)$ be the maximum over all $\Om\in\OmsG$ of the number of \bdbd paths of $\Om$ separating $\ff$ from $\f$. Finally, let 
$\distcurve(\ff,\f):=\min_{\Cyc} \gelletter_\G(\Vint\ind[\Cyc])$,
where
\begin{itemize}
\item the minimum is taken over all Jordan curves $\Cyc$ inside $\Disk$ not passing through any vertices of $\G$, such that the area enclosed by $\Cyc$ intersects the interiors of both $\ff$ and $\f$, 
\item $\Vint\ind[\Cyc]$ is the set of interior vertices of $\G$ located inside $\Cyc$, and
\item $\gelletter_\G(\Vint\ind[\Cyc]):=\min\left(\gelW(\Vint\ind[\Cyc]),\gelB(\Vint\ind[\Cyc])\right)$.
\end{itemize}
 Then 
\begin{equation}\label{eq:conj_dist}
 \distrk(\ff,\f) = \distsep(\ff,\f) = \distcurve(\ff,\f) \quad\text{for all $\ff,\f\in\Faces$}. 
\end{equation}

\label{conj:main}
Let $(X,\omega)$ be an $(n-1)$-shifted symplectic derived stack and let $G$ act on $X$ by symplectomorphisms. 

\begin{enumerate}[label=(\roman*)]
  \item The shifted conormal of the quotient stack $\qstack{X}{G}$ provides a shifted Lagrangian of the shifted cotangent stack: \[ N^* [n] (\qstack{X}{G} \to \mathrm{B}G) \to \Tcot{n}{\mathrm B G},\]

  \item The quotient stack $\qstack{X}{G}$ is lifted to an $n$-shifted Lagrangian in $\Tcot{n}{\mathrm B G}$ if and only if $X$ admits a shifted moment map, or equivalently, the $G$-action on $X$ is Hamiltonian;

  \item For any closed subgroup $H\leq G$, there is an $n$-shifted Lagrangian given by the shifted conormal stack: \[N^* [n] (\mathrm{B}H \to \mathrm{B}G) \longrightarrow \Tcot{n}{\mathrm B G},\] where for $H = *$ this is the topological Dirichlet boundary $\mathfrak{g}^\vee [n-1]$ , and for $H = G$ this is the topological Neumann boundary $\mathrm{B}G$;

  \item The topological gauging from symmetry $G$ to symmetry $H$ is implemented by the topological domain wall between the corresponding Lagrangians:
  \[\begin{tikzcd}
    {(\mathfrak{g}/\mathfrak{h})^\vee [n-1]}
      \arrow[d]
      \arrow[r]
    & {N^* [n] (\mathrm{B}H \to \mathrm{B}G)}
      \arrow[d]
      \arrow[r]
    & {\pt}
    \\ {\mathfrak{g}^\vee [n-1]}
      \arrow[d]
      \arrow[r]
    & {\Tcot{n}{\mathrm B G}}
    & {}
    \\ {\pt}
    & {}
    & {}
  \end{tikzcd};\]

  \item The Hamiltonian reduction of $X$ by $H$ is given by the derived intersection:
  \[\begin{tikzcd}
    {X}
    & {}
    & {\qstack{X}{G} \times_{\Tcot{n}{\mathrm B G}} \mathfrak{g}^\vee [n-1]}
      \arrow[ll,"\sim"']
    \\ {\mu_H^{-1}(0)}
      \arrow[u]
      \arrow[d]
    & {}
    & {\qstack{X}{G} \times_{\Tcot{n}{\mathrm B G}}( \mathfrak{g}/\mathfrak{h})^\vee [n-1]}
      \arrow[u]
      \arrow[d]
      \arrow[ll,"\sim"]
    \\ {\Qstack{X}{H}}
    & {}
    & {\qstack{X}{G} \times_{\Tcot{n}{\mathrm B G}} N^* [n] (\mathrm{B}H \to \mathrm{B}G)} 
      \arrow[ll,"\sim"]
    \end{tikzcd},\] where $\mu_H \colon X \to \mathfrak{h}^\vee [n-1]$ is the shifted moment map to $H$-symmetry.
\end{enumerate}

\label{finovezzoni}
If a compact complex manifold $M$ admits a balanced
