\label{conj:matrixEZ}
The matrix $\nabla_\tau$ is the transpose of
$\nabla_{\tau^\ast}$ for every preorder $\tau$.

\label{conj:zeta}
For every preorder $\tau$ of size $n$ 

\begin{equation} \label{eq:conj-qzeta}
\zZ_q(P_\tau, [-1]_q) = 
(-1)^n \sum_{\mathbf{a} \in \Max(P_\tau)} 
q^{-\cov(\mathbf{a})},
\end{equation}

where $\cov(\mathbf{a})$ is the number of elements 
of $P_\tau$ covered by $\mathbf{a}$ and $[-1]_q = 
-1/q$. In particular,

\begin{equation} \label{eq:conj-zeta}
\zZ(P_\tau,-1) = (-1)^n \, \# \Max(P_\tau) 
\end{equation}

for every preorder $\tau$ of size $n$.

\label{conj:gamma}
The polynomial $h(\tau,t)$ is $\gamma$-positive,
meaning that 

\[ h(\tau,t) = \sum_{i=0}^{\lfloor n/2 \rfloor}
\gamma_i(\tau) t^i (1+t)^{n-2i} \]

for some nonnegative integers $\gamma_0(\tau), 
\gamma_1(\tau),\dots,\gamma_{\lfloor n/2 \rfloor}
(\tau)$, for every preorder $\tau$ of size $n$.
In particular, the vector $h(\tau)$ is palindromic 
and unimodal.

\label{conj:roots}
The polynomial $h(\tau,t)$ has only real roots 
for every preorder $\tau$.

\label{conj:hvector-dual}
We have $h(\tau) = h(\tau^\ast)$ for every 
preorder $\tau$.

\label{conj:double}
The double Ehrhart polynomial $\biE_\tau(u,v)$ 
satisfies the identity

\begin{equation} \label{eq:conj-double}
\biE_\tau(-u,-v) = (-1)^n \, \biE_\tau(u-1,v-1) 
\end{equation}

for every preorder $\tau$ of size $n$.

\label{conj:lattice}
For every preorder $\tau$ of size $n$ there 
exists a finite graded lattice $L_\tau$ of
rank $n$ such that $\zZ(P_\tau,t) = \zZ(L_\tau,
t)$ and

\begin{equation} \label{eq:M-transmute}
\overline{M}_{P_\tau}(x,y) = M_{L_\tau}(x,y). 
\end{equation}

In particular, the rank-generating polynomial 
of $L_\tau$ is equal to $h(\tau,t)$.

