\label{asymhcabcon}
    Let $b\geq 2$ be fixed. Then every sufficiently large odd integer $N$ can be expressed as the sum of a prime and a reversed prime. In particular, if
    \begin{equation}\label{R11def}
        \mathcal{R}_{1,1}(N):=\sum_{\substack{p_1,\rev{p_2}\leq N\\ N=p_1+\rev{p_2}\\ (\rev{p_2},b^3-b)=1}}\log p_1\log p_2,
    \end{equation}
    then, for any $A>0$,
    \begin{equation*}
        \mathcal{R}_{1,1}(N)\sim\mathfrak{S}_2(N)\#\fB(N),
    \end{equation*}
    where
    \begin{equation}\label{sing2eq}
        \fS_2(N):=\prod_{\substack{p\mid b^3-b\\ p\mid N}}\left(1+\frac{1}{p-1}\right)\prod_{\substack{p\mid b^3-b\\ p\nmid N}}\left(1-\frac{1}{(p-1)^2}\right).
    \end{equation}

\label{purecon}
    Let $b\geq 2$ and $k\geq 2$ be fixed. Then, for any $A>0$,
    \begin{equation}\label{r0kasym}
        \mathcal{R}_{0,k}(N)=\mathfrak{S}_k(N)\cS_{0,k}(N)+O_{b,A}\left(\frac{N^{k-1}}{(\log N)^A}\right),
    \end{equation}
    where
    \begin{equation}\label{singkeq}
        \mathfrak{S}_k(N):=\prod_{\substack{p\mid b^3-b\\ p\mid N}}\left(1-\left(\frac{-1}{p-1}\right)^{k-1}\right)\prod_{\substack{p\mid b^3-b\\ p\nmid N}}\left(1-\left(\frac{-1}{p-1}\right)^k\right)
    \end{equation}
    and
    \begin{equation}\label{S0kdef}
       \cS_{0,k}(N):=\sum_{\substack{n_1,\ldots,n_k\leq N\\n_1+\cdots+n_k=N\\(\rev{n_1}\cdots\rev{n_k},b)=1}}1. 
    \end{equation}

