\label{conjIntrohyperkahler} Let $G$ be a semisimple group over $\CC$ and $G^\sc$ be its simply-connected cover.
\begin{enumerate}
    \item There exists a hyperK\"ahler structure on $\cM^\c_G$ such that $J^{G}_{G^\sc}$ as a complex manifold is obtained from $\cM^\c_G$ by  hyperK\"ahler rotation. In particular, there is a canonical isomorphism on cohomology
    \begin{equation*}
        \cohog{*}{\cM^\c_G,\QQ}\isom \cohog{*}{J^G_{G^\sc}, \QQ}.
    \end{equation*}
    \item The above isomorphism sends $P_{i}\cohog{*}{\cM^\c_G,\QQ}$, the $i^{\textup{th}}$ piece of the perverse filtration associated to the Hitchin fibration $\cM^\c_G\to \cA_G$, isomorphically to the $2i^{\textup{th}}$ piece of the weight filtration $W_{2i}\cohog{*}{J^G_{G^\sc},\QQ}$, for $i=0,1,\cdots, 2r$.
\end{enumerate}

\label{c:coho MG} Assume $G$ is semisimple. The perverse filtration on $\cohog{*}{\cM^\c_G}$ is compatible with the decomposition \eqref{decomp coho MG}. Moreover, for each $(J,\chi)\in \frS^{\min}_G$, we have
\begin{equation}
    P_i\left(\cohog{*}{\ov\PP_J, \ov{\cF^0_{J,\chi}}}[-2|J|](-|J|)\right)=\t_{\le i+|J|}\left(\cohog{*}{\ov\PP_J, \ov{\cF^0_{J,\chi}}}[-2|J|](-|J|)\right), \quad i\in \ZZ.
\end{equation}
Here $\t_{\le n}$ denotes the truncation in the usual t-structure of $D(\Vect)$.

In particular, for $0\le i\le 2r$,
\begin{equation}
    \Gr^P_i\cohog{*}{\cM^\c_G}\cong \bigoplus_{(J,\chi)\in \frS^{\min}_G, |J|\le\min\{i,2r-i\}}\cohog{i-|J|}{\ov\PP_J, \ov{\cF^0_{J,\chi}}}(-|J|).
\end{equation}

\label{c:P=W} Let $G$ be semisimple over $\CC$.
    Under the homeomorphism $\cM^\c_G\simeq J^{G}_{G^\sc}$ in Conjecture \ref{c:HK}, the induced isomorphism on cohomology
    \begin{equation*}
        \cohog{*}{\cM^\c_G,\QQ}\isom \cohog{*}{J^G_{G^\sc}, \QQ}
    \end{equation*}
    sends $P_{i}\cohog{*}{\cM^\c_G,\QQ}$ isomorphically to $W_{2i}\cohog{*}{J^G_{G^\sc},\QQ}$, for $i=0,1,\cdots, 2r$.

\label{c:coho J}
    Let $G$ be semisimple over $\CC$. Then 
    \begin{enumerate}
        \item $\cohog{i}{J^G_{G^\sc},\QQ}=0$ for odd $i$.
        \item For $0\le j\le r$ and $j\le i\le 2j$, we have
        \begin{equation}
            \dim \Gr^W_{2i}\cohog{2j}{J^G_{G^\sc},\QQ}=\sum_{d\in \NN, \wt I_d\ne \vn, 2j-i=r-r_d+1}\ph(d).
        \end{equation}
        Otherwise $\Gr^W_{2i}\cohog{2j}{J^G_{G^\sc},\QQ}=0$.
        In particular, $\dim \cohog{2}{J^G_{G^\sc},\QQ}=1$ and it is pure of weight $4$. \footnote{This follows from the observation that $r_1=r+1$ and $r_d<r$ for $d>1$.}
        \item Let $\y\in \cohog{2}{J^G_{G^\sc},\QQ}$ be a nonzero element (which has weight $4$ by part (2)). Then the cup product action of $\y$ on $\cohog{*}{J^G_{G^\sc},\QQ}$ satisfies the hard Lefschetz property with respect to the weight filtration: for $0\le i\le r$, cupping with $\y^i$ induces an isomorphism
        \begin{equation}
            \cup \y^i: \Gr^W_{2r-2i}\cohog{*}{J^G_{G^\sc},\QQ}\isom \Gr^W_{2r+2i}\cohog{*+2i}{J^G_{G^\sc},\QQ}.
        \end{equation}
    \end{enumerate}

