We conjecture that this choice of AMP algorithm will converge to equilibrium, as $t\to\infty$. By equilibrium, we mean the following two statements:
   \begin{enumerate}
       \item The state evolution parameters converge $q_t \to q_{\ast}\in\RR^L$, where $q_{\ast}$ is the solution to the following fixed-point equation
       \begin{equation}
           q_{\ast} = 1 - \diag\sbr{\rbr{\Diag\rbr{\lambda\odot q_{\ast}}+B^{-1}}^{-1}}.
       \end{equation}
       In comparison with our self-consistent equations \eqref{eq: self-consistent eq matrix}, it holds that $q_{\ast}^{(l)}=1-M_{ll}(1)$.

       \item Let $m_t\in\RR^{nL}$ be the concatenation of $m_t^{(1)},\ldots,m_t^{(L)}$. Then it also converges to equilibrium, as $m_t\to m_{\ast}\in\RR^{nL}$, where $m_{\ast}$ satisfies that
       \begin{equation}\label{eq:AMP variable equilibrium}
            m_{\ast}^{(l)}=\sqrt{\frac{\lambda_l}{n}} A^{(l)} \cE_\ast^{(l)}(m_{\ast})-\lambda_l\rbr{1-q_{\ast}^{(l)}}\cE_\ast^{(l)}(m_{\ast}),
        \end{equation}
        where we use $\cE_{\ast}$ to denote the denoiser with the limiting state evolution parameters $q_{\ast}$. Moreover, we have the following distributional result
        \begin{equation}\label{eq:AMP distributional}
            m_{\ast}^{(l)} \overset{d.}{\approx} \lambda_lq_{\ast}^{(l)} X^{(l)}+\sqrt{\lambda_l q_{\ast}^{(l)}}\cN(0,I_n),\quad l\in[L].
        \end{equation}
        Moreover, we also have $X^{(l)\top}\cE^{(l)}_\ast\rbr{m_{\ast}}/n \overset{d.}{\approx} q_{\ast}^{(l)}$.
   \end{enumerate}

