Let $\mat{\Omega} \in \field^{n \times \ell}$ and $\mat{\Psi} \in \field^{d \times k}$ be any full-rank random embeddings.
    Then the following optimality results hold.

    \begin{enumerate}[label=(\alph*)]
        \item \textbf{Sketch-and-solve.} For any problem dimensions $d, p \in \mathbb{N}$, any rank parameter $r \in \mathbb{N}$ with $r + \alpha_\field < \ell$, and any algorithm $\mathrm{ALG} : \field^{n \times \ell} \times \field^{\ell \times d} \times \field^{\ell \times p} \to \field^{d \times p}$,

        \begin{equation*}
            \sup_{\substack{\mat{A}\in \field^{n\times d},\: \mat{B} \in \field^{n\times p} \\
            \rank(\mat{A}) = r}} \frac{\expect \norm{\mat{B} - \mat{A}\cdot\mathrm{ALG}(\mat{\Omega},\mat{\Omega}^*\mat{A},\mat{\Omega}^* \mat{B})}_{\rm F}^2}{\norm{\mat{B} - \mat{A} \mat{A}^+ \mat{B}}_{\rm F}^2} 
            \ge 1 + \frac{n-\ell}{n-r}\, \frac{r}{\ell - r - \alpha_\field}.
        \end{equation*}
        \item \textbf{Randomized SVD.} 
        For any problem dimension $d \in \mathbb{N}$, any rank parameters $q,r \in \mathbb{N}$ with $q + \alpha_{\field} < \ell \leq r$, and any algorithm $\mathrm{ALG} : \field^{n \times \ell} \times \field^{d \times \ell} \times \field^{n \times \ell} \to \field^{d \times n}$,

        \begin{equation*}
            \sup_{\substack{\mat{A} \in \field^{d \times n} \\ \rank(\mat{A}) = r}} \frac{\expect \norm{\mat{A} - \mathrm{ALG}(\mat{\Omega},\mat{A}\mat{\Omega},\mat{A}^*\mat{A}\mat{\Omega})}_{\rm F}^2}{\norm{\mat{A} - \lowrank{\mat{A}}_q}_{\rm F}^2} \ge \frac{r -\ell}{r - q} \left(1 + \frac{q}{\ell - q - \alpha_\field}\right).
        \end{equation*}
        \item \textbf{Randomized Nystr\"om.} 
        For any rank parameters $q, r \in \mathbb{N}$ with $q + \alpha_{\field} < \ell \leq r$ and any algorithm $\mathrm{ALG} : \field^{\ell \times n}\times \field^{\ell \times n} \to \field^{n\times n}$,

        \begin{equation*}
            \sup_{\substack{\mat{H} \in \field^{n\times n} \text{ psd} \\ \rank(\mat{H}) = r}} \frac{\expect \tr\bigl(\mat{H} - \mathrm{ALG}(\mat{\Omega},\mat{H}\mat{\Omega})\bigr)}{\tr(\mat{H} - \lowrank{\mat{H}}_q)} 
            \ge \frac{r-\ell}{r-q}\, \left(1 + \frac{q}{\ell - q - \alpha_\field}\right).
        \end{equation*}
    \end{enumerate}

