\label{conj:global-picky}
Let $G$ be a finite group, let $p$ be a prime, let $P\in\Syl_p(G)$, and let
$\mathcal P$ be a set of picky $p$-elements contained in $P$. Then there exists
a bijection
$$
f:\Irr^{\mathcal P}(G)\longrightarrow \Irr^{\mathcal P}(\bN_G(P))
$$
such that for every $\chi\in\Irr^{\mathcal P}(G)$:
\begin{enumerate}[label=(\arabic*)]
\item $\chi(1)_p=f(\chi)(1)_p$;
\item $\mathbb Q(\chi(x))=\mathbb Q(f(\chi)(x))$ for every $x\in\mathcal P$;
\item $f(\Irr^x(G))=\Irr^x(\bN_G(P))$ for every $x\in\mathcal P$.
\end{enumerate}

\label{conj:reduced-p-section}
Let $G$ be a finite group, let $p$ be a prime, let $P\in \Syl_p(G)$, and let
$x\in P$. Then there exists a bijection
$$
f:\Irr^{R_p(x)}(G)\longrightarrow \Irr^{R_p(x)}(\Sub_G(x))
$$
such that
\begin{enumerate}
\item $\chi(1)_p=f(\chi)(1)_p$ for every $\chi\in \Irr^{R_p(x)}(G)$;
\item $\chi(g)=0$ if and only if $f(\chi)(g)=0$ for every $g\in R_p(x)$ and every
      $\chi\in \Irr^{R_p(x)}(G)$;
\item $\mathbb Q(\chi(g))=\mathbb Q(f(\chi)(g))$ for every $g\in R_p(x)$ and every
      $\chi\in \Irr^{R_p(x)}(G)$;
\item for every $g\in R_p(x)$, the restriction of $f$ to $\Irr^g(G)$ is a bijection
      onto $\Irr^g(\Sub_G(x))$.
\end{enumerate}

\label{conj:abelian-sylow-p-section}
Let $G$ be a finite group with abelian Sylow $p$-subgroups. Let $P\in \Syl_p(G)$
and let $x\in P$ be picky. Then there exists a bijection
$$
f:\Irr^{S_p(x)}(G)\longrightarrow \Irr^{S_p(x)}(\Sub_G(x))
$$
such that
\begin{enumerate}
\item $\chi(1)_p=f(\chi)(1)_p$ for every $\chi\in \Irr^{S_p(x)}(G)$;
\item $\chi(g)=\pm f(\chi)(g)$ for every $g\in S_p(x)$ and every
      $\chi\in \Irr^{S_p(x)}(G)$;
\item for every $g\in S_p(x)$, the restriction of $f$ to $\Irr^g(G)$ is a bijection
      onto $\Irr^g(\Sub_G(x))$.
\end{enumerate}

Let $G$ be a finite group, let $\pi$ be a set of primes, and let $H$ be a nilpotent
Hall $\pi$-subgroup of $G$. Then there exists a bijection
