\HFS\ is NP-complete if $H$ has at least two components that are subdivided bistars, or if $H$ has a component that is neither a subdivided star nor a subdivided bistar.
Furthermore, assuming the Exponential Time Hypothesis (ETH), the problem cannot be solved in time $2^{o(k)}\cdot n^{O(1)}$.

{\rm (\cite[Conjecture 7.1]{24KY})}
\label{conj: Kim and Yoo}
Let $\lambda$ be a partition with $\ell(\lambda) = 2$.
\footnote{In \cite{24KY}, the conjecture is stated for partitions $\lambda$ with $\ell(\lambda)\le 2$. When $\ell(\lambda)=1$, we have $\IGLT(\lambda)=\SYT(\lambda)$, so the conjecture holds trivially. Thus, in this paper, we restrict our attention to partitions $\lambda$ with $\ell(\lambda)=2$.}
For each $l_\lambda \le m \le n$, there exists a partition $\{\calE_\mu \mid \mu \in \mathsf{Par}(\lambda; m)\}$ of $\calE_{\lambda;m}$ satisfying the following two conditions:
\begin{enumerate}[label = {\bf C\arabic*.}]
\item For each $\mu \in \mathsf{Par}(\lambda; m)$, $\sum_{E \in \calE_\mu} \ch([\bfG_E]) = s_{\mu}$.
\item For each $\mu \in \mathsf{Par}(\lambda; m)$, there exists a total order $\prec_\mu$ on $\calE_\mu = \{E_1 \prec_\mu E_2 \prec_\mu \cdots \prec_\mu E_{|\calE_\mu|}\}$ and a filtration 
\[
M^\mu_0 = \{0\} \subseteq M^\mu_1 \subseteq M^\mu_2 \subseteq \cdots \subseteq M^\mu_{|\calE_\mu|} = X_\mu
\]
of $H_m(0)$-modules such that $\bfG_{E_i} \cong M^\mu_{i}/M^\mu_{i-1}$ for all $1 \le i \le |\calE_\mu|$.
\end{enumerate}

\label{hol_conj}
If $\ell \notin\overline{\mathcal{E}_F^{\ord}}$ and $\ell>1$ then $\Ztop{(\ell)}(F,s)_\zero$  is holomorphic on $\CC$
and, actually, vanishes.

\label{conj:cdp}
Let $G$ be a finite group, $p$ a prime, and $P$ a Sylow $p$-subgroup of
$G$. Let
\[
p^b=\max \cd(P)
\qquad\text{and}\qquad
p^f=\max \cd_p(G).
\]
Then:
\begin{enumerate}
\item $\dl(P)$ is bounded in terms of $f$;
\item $b$ is bounded in terms of $f$;
\item $\dl(P)$ is bounded in terms of $|\cd_p(G)|$.
\end{enumerate}
Moreover, the bounds in (1) and (3) should be logarithmic.

\label{conj:ht}
Let $G$ be a finite group, $p$ a prime, and $B$ a $p$-block of $G$ with
defect group $D$. Let
\[
p^b=\max \cd(D)
\qquad\text{and}\qquad
e=\max \operatorname{ht}(B).
\]
Then:
\begin{enumerate}
\item $\dl(D)$ is bounded in terms of $e$;
\item $b$ is bounded in terms of $e$;
\item $\dl(D)$ is bounded in terms of $|\operatorname{ht}(B)|$.
\end{enumerate}
Moreover, the bounds in (1) and (3) should be logarithmic.

\label{conj:picky}
Let $G$ be a finite group, let $p$ be a prime, and let $x$ be a $p$-element
lying in a unique Sylow $p$-subgroup. Then there exists a bijection
\[
f:\Irr^x(G)\longrightarrow \Irr^x(N_G(P))
\]
such that:
\begin{enumerate}
\item $\chi(1)_p=f(\chi)(1)_p$ for all $\chi\in\Irr^x(G)$;
\item $\mathbb{Q}(\chi(x))=\mathbb{Q}(f(\chi)(x))$ for all
      $\chi\in\Irr^x(G)$.
\end{enumerate}

\label{conj:sub}
Let $G$ be a finite group, let $p$ be a prime, and let $x$ be a
$p$-element. Then there exists a bijection
\[
f:\Irr^x(G)\longrightarrow \Irr^x(\Sub_G(x))
\]
such that:
\begin{enumerate}
\item $\chi(1)_p=f(\chi)(1)_p$ for all $\chi\in\Irr^x(G)$;
\item $\mathbb{Q}(\chi(x))=\mathbb{Q}(f(\chi)(x))$ for all
      $\chi\in\Irr^x(G)$.
\end{enumerate}

\label{conjecture:no_wandering_continua}
Let $G$ be a cocompact Kleinian group. Suppose $K\subset S^2_\infty$ is a compact connected
set disjoint from all its $G$-translates. Then $K$ consists of a single point.

\label{conjecture:quasicircles}
Let $f:S^1 \to \CP^1$ be a CaTherine wheel arising from an expanding Thurston map. 
Then $f$ is a $K$-CaTherine wheel for some $K$.

\label{conj:bigconjecture}
    For generic choices of $u \in \mathbb{C}^{n+1}$, we have 
    \begin{enumerate}
        \item The holonomic rank of the matroid hypergeometric system $M_L(u)$ is the absolute value of the topological Euler characteristic of $(\mathbb{P}^d \setminus {\cal A}) \setminus V_z\simeq (L^{-1}\cap T)\setminus H_z$. That is, it equals $\beta(L) + (-1)^{d-1} \chi^*$, where $\chi^*$ is the generic Euler characteristic from Question \ref{q:genericeuler}.
        \item The characteristic variety of the matroid hypergeometric system $M_L(u)$ is $W$ from  \eqref{eq:W}.
        \item  The singular locus of $M_L(u)$ is the vanishing locus of the pricipal matroid determinant $V(E_L)$ in $\C^{n+1}$.
        \item $M_L(u)$ is a regular holonomic $D_Z$-module.
    \end{enumerate}

\label{conj:polynomial-lifting}
There are constants \(C,a,C_0>0\) such that:
\begin{enumerate}[label=\textup{(\arabic*)}, leftmargin=*]
    \item every \(2\)-modular witness of size at least \(C_0m\) contains a \(4\)-modular witness of exactly \(m\) vertices;
    \item for every power of two \(q\ge 4\), every \(q\)-modular witness of size at least \(Cq^a m\) contains a \(2q\)-modular witness of exactly \(m\) vertices.
\end{enumerate}

\label{lonelyconj}
  Let $u_1,\ldots,u_{k+1}$ be distinct real numbers. For each $i \in\{1,\ldots,k+1\}$, there is a real number $t$ such that
