			\Lambda(\theta)=\theta\inf_{\zeta:\zeta(\{0\})=\theta}\Pari(\zeta).
		\end{equation}
		There exists an open subset $D\subset\dR$ containing $[\inf_\zeta \Pari(\zeta),+\infty)$ such that for every $f\in D$,
		\begin{equation*}
			\lim_{\ve\to 0}\lim_{N\to\infty}
			\frac{1}{N}\log\dE\bigl[\mc{N}_\ve(f)\bigr]=-\Lambda^*(f)=\inf_\theta \bigl(\Lambda(\theta)-\theta f\bigr).
		\end{equation*}

\label{conj:quenched formula}
		Define
		\begin{equation}\label{def:tildeLambda}
			\tilde{\Lambda}(\theta)=\theta\inf_{\zeta:\zeta([0,\sup(\supp \zeta)))=\theta}\Pari(\zeta).
		\end{equation}
