		\begin{equation}\label{eq:quenched conj}
			\lim_{\ve\to 0}\lim_{N\to\infty}
			\frac{1}{N}\dE\bigl[\log\mc{N}_\ve(f)\bigr]=-\tilde{\Lambda}^*(f)=\inf_\theta \bigl(\tilde{\Lambda}(\theta)-\theta f\bigr).
