\label{conj:rate}
In the structured regime $H_{\mathrm{struct}} < \frac{1}{2}\log_2 M$, the optimal number of permutations satisfies
\begin{equation}
n^*(\mathbf{R}) \;\approx\; \lceil 2^{H_{\mathrm{struct}}(\mathbf{R})} \rceil,
\end{equation}
with $n^*/2^{H_{\mathrm{struct}}} \in [0.74, 1.20]$ confirmed empirically. In the diffuse regime $H_{\mathrm{struct}} \to \log_2 M$, $n^* = \Theta(M)$.

\label{conj:continuous-knn}
Let $n$ points be drawn i.i.d. uniformly from the unit circle $\mathbb{S}^1$ (or the interval $[0,1]$ with periodic boundary conditions). Construct a graph by sequentially inserting the points and connecting each new point to its $K$ nearest already-inserted neighbors. For every $\varepsilon > 0$, there exists a constant $K_0 = K_0(\varepsilon)$ such that for all $K \geq K_0$ and sufficiently large $n$, if $s$ and $t$ are chosen uniformly at random from the $n$ points, then with probability at least $1 - \varepsilon$:
\begin{enumerate}[label=(\roman*)]
\item the greedy walk from $s$ successfully reaches $t$, and
\item the walk completes in at most $C(\varepsilon) \log n$ steps, where $C(\varepsilon)$ is a constant depending only on $\varepsilon$.
\end{enumerate}

\label{acyclicquiverconj}
Let $A$ be an algebra of finite global dimension.
\begin{enumerate}
    \item If $A$ is twisted fractionally Calabi--Yau, then $A$ has an acyclic Ext-quiver.
    \item If $A$ is $d$-representation-finite, then $A$ has an acyclic Ext-quiver.
\end{enumerate}

\label{Gibbon}
An entire critical point $\begin{pmatrix}u, A\end{pmatrix}^T$ on $\mathbb{R}^{n+2}$ satisfying
	\begin{align*}
	\lim_{R \rightarrow \infty} \frac{1}{\left|B_R^n\right|} \int_{B_R^{n+2}} e_{\e}\begin{pmatrix}u\\ A\end{pmatrix}=2 \pi
	\end{align*}
and, writing any $x \in \mathbb{R}^{n+2}$ as $x=(y, z) \in \mathbb{R}^2 \times \mathbb{R}^n$, also satisfying
	\begin{align*}
	\lim_{|z| \rightarrow \infty}|u(y, z)|=1, \quad \text{ uniformly in } z,
	\end{align*}
is necessarily two-dimensional. More precisely, it is the pullback through the projection $\mathbb{R}^{n+2} \rightarrow \mathbb{R}^2$ of the standard solution in $\mathbb{R}^2$ with degree $\pm 1$, up to translation and change of gauge.

