For $n>34$, we have
\begin{align*}
\mathcal{M}_e(n)>\mathcal{M}_o(n).
\end{align*}

Let $n>10$. Then 
\begin{align*}
\mathcal{M}_e(n)-\mathcal{M}_o(n)<q(n),
\end{align*} 
where $q(n)$ is the number of partitions of $n$ into distinct parts.

For any positive integer $n>27$, we have 
\begin{align*}
\overline{\mathcal{M}}_e(n)>\overline{\mathcal{M}}_o(n).
\end{align*}
In other words, the number of overpartitions of $n$ with an even number of missing integers is always more than the number of overpartitions of $n$ with an odd number of missing integers for $n>27$.

\label{conj: Universality}
  Let
  $\left\{ \Gamma^{\left(\beta\right)}\right\} _{\beta\nearrow\infty}$
  be any sequence of standard graphs, with the first Betti numbers
  $\beta\to\infty$.  Choosing arbitrary rationally independent edge
  lengths for each $\Gamma^{\left(\beta\right)}$, let
  $\sigma^{\left(\beta\right)}$ denote its nodal surplus random
  variable. Then, the variance has linear growth
  $\var\left(\sigma^{(\beta)}\right) \sim \beta$ and in the limit of
  $\beta\rightarrow\infty$,
  \begin{equation}\label{eq: universality}
    \frac{\sigma^{\left(\beta\right)}-\frac{\beta}{2}}
    {\sqrt{\var\left(\sigma^{(\beta)}\right)}}
    \xrightarrow{\ \mathcal{D}\ }
    N(0,1),
  \end{equation}
  where the convergence is in distribution and $N(0,1)$ is the
  standard normal distribution.

