For $d \equiv 0 \pmod{8}$, $d \geq 8$, the following are equivalent:
\begin{enumerate}[(a)]
\item The Cohn--Elkies LP bound is sharp in dimension~$d$.
\item The following two sub-conditions both hold:
  \begin{enumerate}[(b1)]
  \item $\dim S_{d/2}(\SL_2(\Z)) \leq 1$;
  \item there exists an even unimodular lattice $\Lambda$ in $\R^d$ that is \emph{distinguished} in the following sense: either $\Lambda$ is the \emph{unique} even unimodular lattice of rank~$d$ (as for $d = 8$), or $\Lambda$ is the \emph{unique rootless} (no vectors of squared norm~2) even unimodular lattice of rank~$d$ (as for $d = 24$).
  \end{enumerate}
\item There exists an extremal Narain CFT with $U(1)^{d/2} \times U(1)^{d/2}$ symmetry and central charge $c = \bar{c} = d/2$ that saturates the modular bootstrap bound of Hartman--Maz\'a\v{c}--Rastelli~\cite{HartmanMazacRastelli2019}.
\end{enumerate}

