T_n(f_{2,1}) & T_n(f_{2,2}) & \ddots & \vdots  \\
 \vdots & \ddots & \ddots & T_n(f_{k-1 , k}) \\
 T_n(f_{k,1}) & \dots & T_n(f_{k, k-1}) & T_n(f_{k, k})
\end{bmatrix},
\end{equation*}
where, for every $i,j=1,\dots, k,$ $f_{i,j} \in L^{\infty}([-\pi,\pi])$ and real-valued almost everywhere with $T_n(f_{i,j}) $ Hermitian positive definite whenever $i \neq j$, or $f_{i,j}=0$ almost everywhere. Assume that, for every cycle $i_1,\dots,i_k,i_{k+1}$, we have
\begin{equation*}
\prod_{l=1}^{k} f_{i_l,i_{l+1}} (\theta) = \prod_{l=1}^{k} f_{i_{l+1},i_l} (\theta)
\end{equation*}
for a.e. $\theta \in [-\pi,\pi]$, where $i_{k+1}=i_1$.
Then,
\begin{equation*}
 \{\mathcal{A}_n\}_n \sim_{\lambda}  \begin{bmatrix}
f_{1,1} & f_{1,2} & \dots &  f_{1,k}\\
f_{2,1} & f_{2,2} & \ddots & \vdots \\
\vdots & \ddots & \ddots & f_{k-1 , k} \\
f_{k,1} & \dots & f_{k, k-1} & f_{k, k}
\end{bmatrix}.
\end{equation*}

\label{conj:vojta}
Let $X$ be a smooth projective variety defined over a number field $k$, $K$ be a canonical divisor, $A$ be an ample divisor, and $D$ be a reduced normal-crossings divisor.  Let $S$ be a finite subset of $M_k$.  Then given $\epsilon >0$, there exists a Zariski-closed $Z = Z_\epsilon \neq X$ such that
\begin{equation}\label{eq:vojtacon}
\sum_{v\in S} \lambda_v(D, P) + h(K,P) \le \epsilon h(A, P)
\end{equation}
for all $P\in (X\setminus Z)(k)$.

\label{conjecture}
Let $\Sigma^H_{1,N}$ be the covariance matrix of $N$ unit increments of fractional Brownian motion and $P_k$ be the $N\times 2N$ matrix given by
\begin{equation}
\label{eq: projection matrix P}
   P_k = \left( {\bf 0}_{N\times k}, I_{N}, {\bf 0}_{N\times (N-k)}\right),  
\end{equation}
which projects a $2N\times 1$ vector to the sub-vector with coordinates $(k+1,N+k)$. Set 
