\label{facedecomp}
    We have a face decomposition of the magnitude.
    \begin{align*}
           \mathrm{Mag}(\A)&=\sum_{F\in\FF(\A)}\mathrm{Mag}^{\circ}(\A_F)=\sum_{F\in\FF(\A)}(-1)^{\codim F}q^{\#\A_F}\mathrm{Mag}(\A_F)\\
           &=\sum_{X\in L(\A)}c^X\mathrm{Mag}^{\circ}(\A_X)=\sum_{X\in L(\A)}(-1)^{\codim X}c^Xq^{\#\A_X}\mathrm{Mag}(\A_X),
    \end{align*}
    where $c^X=\#\mathrm{Ch}(\A^X)$. Equivalently,
    \begin{align*}
            \mathrm{Mag}(\A)&=\frac{\sum_{F\in\FF(\A)\setminus\{\cap\A\}}\mathrm{Mag}^{\circ}(\A_F)}{1-(-1)^{\mathrm{rank}\A}q^{\#\A}}=\frac{\sum_{F\in\FF(\A)\setminus\{\cap\A\}}(-1)^{\codim F}q^{\#\A_F}\mathrm{Mag}(\A_F)}{1-(-1)^{\mathrm{rank}\A}q^{\#\A}}\\
            &=\frac{\sum_{X\in L(\A)\setminus\{\cap\A\}}c^X\mathrm{Mag}^{\circ}(\A_X)}{1-(-1)^{\mathrm{rank}\A}q^{\#\A}}=\frac{\sum_{X\in L(\A)\setminus\{\cap\A\}}(-1)^{\codim X}c^Xq^{\#\A_X}\mathrm{Mag}(\A_X)}{1-(-1)^{\mathrm{rank}\A}q^{\#\A}}.
    \end{align*}

\label{conj:blind}
