\label{conj:gaat}
Let $\mathbf{x} = \mathbf{s} + \mathbf{n} \in \mathbb{C}^M$, where $\mathbf{s}$ is deterministic and $\mathbf{n} \sim \mathcal{CN}(\mathbf{0}, \sigma^2 \mathbf{I}_M)$.  Let $G$ be a finite group with unitary representation $\pi: G \to U(M)$, and let $f: \mathbb{C}^M \to \mathcal{V}$ be a $G$-equivariant statistic (i.e., there exists an induced action $\tilde{\pi}$ on $\mathcal{V}$ such that $f(\pi_g(\mathbf{x})) = \tilde{\pi}_g(f(\mathbf{x}))$ for all $g$).  Then the group-averaged estimator $\hat{\theta}_G = \frac{1}{|G|}\sum_{g \in G} f(\pi_g(\mathbf{x}))$ satisfies:
\begin{enumerate}
\item[(i)] $E[\hat{\theta}_G] = \theta_f^G$, the projection of $E[f(\mathbf{x})]$ onto the $G$-invariant subspace of $\mathcal{V}$.
\item[(ii)] $\mathrm{Var}(\hat{\theta}_G) \leq C(f, \mathbf{s}) / d_{\mathrm{eff}}(G, f)$, where $C$ depends on $f$ and $\mathbf{s}$ but not on $G$.
\item[(iii)] For $L$ independent observations each processed with group $G$: $\mathrm{Var}(\hat{\theta}_{G,L}) \leq C(f, \mathbf{s}) / (d_{\mathrm{eff}} \cdot L)$.
\item[(iv)] Setting $G = \{e\}$ and $L = N$ recovers the classical law of large numbers with $\mathrm{Var} \propto 1/N$.
\end{enumerate}

\label{conj:prime_zeta}
Let $H_N=L_N^2$ be the order-$4$ coherence Hamiltonian built from the first $N$ primes, with divergence matrix $\delta_{ij}$ satisfying
\begin{itemize}
\item Symmetry: $\delta_{ij}=\delta_{ji}$, $\delta_{ii}=0$;
\item Logarithmic scaling: $\delta_{ij}=\mathcal{O}(|\log p_i-\log p_j|)$ for $p_i\neq p_j$.
\end{itemize}

Define
 the rescaled eigenvalues
\begin{equation}
\widetilde{\lambda}_k=\frac{2\pi}{\log N}\,\lambda_k .
\end{equation}
Then, as $N\to\infty$, the local statistics of $\{\widetilde{\lambda}_k\}$ asymptotically approximate those of the normalized ordinates $\{\gamma_n\}$ of the Riemann zeta zeros, and the corresponding coherence spectral dimension stabilizes near $d_s\simeq0.5$.
This scaling agrees numerically with random-matrix predictions for the GUE model of the zeta spectrum~\cite{montgomery1973pair,odlyzko1987zero,mehta2004random}.

