\cite[Conjecture 1]{stanton-fake} \label{conjecture:conjecture-stanton}
    Let $\mathbf{a}=(a_1, \ldots, a_n)$ be a sequence of non-negative integers.
    If
    \begin{equation}
        \frac{\prod_{i=1}^n (1-q^{m+i})^{a_i}}{\prod_{i=1}^n (1-q^i)^{a_i}}. \label{equation:stanton-fraction}
    \end{equation}
    is a polynomial for all non-negative integers~$m$ and $\mathbf{a}$ is symmetric, then \eqref{equation:stanton-fraction} has non-negative integer coefficients for all $m$.

\cite[Conjecture 1]{gatzweiler-krattenthaler-positivity} \label{conjecture:conjecture-gk}
    Let $n, k, l \in \ZZ_{\geq 0}$. If
    \begin{equation}
        \frac{\binom{n}{k}_q}{\binom{n}{l}_q} = \frac{[l]_q![n-l]_q!}{[k]_q![n-k]_q!} = \frac{\prod_{i=1}^l (1-q^i) \prod_{i=1}^{n-l} (1-q^i)}{\prod_{i=1}^k (1-q^i) \prod_{i=1}^{n-k} (1-q^i)} \label{equation:GK}
    \end{equation}
    is a polynomial, then it has non-negative integer coefficients.

\cite[Conjecture 4]{gatzweiler-krattenthaler-positivity} \label{conjecture:conjecture-stanton-gk}
    Let $m, n$ be positive integers with $m \geq n$, and let $\mathbf{a}$ be a sequence of non-negative integers.
