\[
\begin{tikzcd}
    \Pi_{\phi_{v}}^{\tn{Kott}_{v}^{1/\infty}} \arrow{d} \arrow["\iota_{\phi_{v},\mathfrak{w}_{v}}"]{r} & \tn{Irr}(S_{\phi_{v}}^{+,\natural}) \arrow{d} \\
    B_{e}(G^{*}_{F_{v}})_{\tn{basic}} \arrow{r} & X^{*}(Z(\widehat{G^{*}})^{\Gamma_{v},+}).
    \end{tikzcd}
\]
The bottom map is the composition of the map from the local analogue \cite[Th\'{e}or\`{e}me 9.12]{Fargues} of Theorem \ref{TNgp}, with the isomorphism $\pi_{1}(G^{*})^{e}_{\Gamma_{v}} \xrightarrow{\sim} X^{*}(Z(\widehat{G^{*}})^{\Gamma_{v},+}$ from \cite[Proposition 12.1]{Fargues}.

Moreover, the bijection $\iota_{\phi_{v},\mathfrak{w}_{v}}$ recovers the bijections
\begin{equation*}
\Pi_{\phi_{v}}^{\tn{Kal}_{v}} \to \tn{Irr}(\pi_{0}(S_{\phi_{v}}^{+})), \hspace{1mm} \Pi_{\phi_{v}}^{\tn{Kott}_{v}} \to \tn{Irr}(S_{\phi_{v}}^{\natural})
\end{equation*}
(recall that $S_{\phi_{v}}^{\natural} := S_{\phi_{v}}/(S_{\phi_{v}} \cap \widehat{G}_{\tn{der}})^{\circ}$) from \cite[Conjecture 6.13.(3)]{Taibi22} and \cite[Conjecture 6.13.(2)]{Taibi22}, respectively, via the maps on irreducible representations induced by the surjective homomorphisms
\begin{equation*}
S_{\phi_{v}}^{+,\natural} \to \pi_{0}(S_{\phi_{v}}^{+}), \hspace{1mm} S_{\phi_{v}}^{+,\natural} \to S_{\phi_{v}}^{\natural},
\end{equation*} 
respectively.

