Applying the \emph{type~1 boundary procedure} of Theorem~\ref{thm:bordspectre}
to the following pairs
$(\partial_{\alpha}\mathcal{R}_1(0,\beta),\,\mathcal{R}_2(0,\beta))$:

\begin{itemize}

\item
\begin{equation}\label{couple1}
\left(
\frac{r^2 - r_1^2 r_2^2 |\beta|^2}{1 - r^2 |\beta|^2},
\; 0
\right),
\end{equation}
where the parameter $r$ is defined by $r^2 = \frac{r_1^2 + r_2^2}{2}$,
yields the outer spectral boundary.

\item
\begin{equation}\label{couple2}
\left(
\frac{(4|\beta|^2 r_{\min}^2 - 1)(4|\beta|^2 r_{\max}^2 - 1)}
{8|\beta|^4 (r_{\max}^2 - r_{\min}^2)} - 1,
\; -\frac{1}{2\beta}
\right),
\end{equation}
where $r_{\max}=\max(r_1,r_2)$ and $r_{\min}=\min(r_1,r_2)$,
generates an additional spectral boundary, which may be empty if
Eq.~\eqref{sol1} admits no solution.

\item
When $\dfrac{1}{r_1^2}+\dfrac{1}{r_2^2}\leq 2$, there exists an inner spectral boundary
given by the circle centered at the origin with radius
\begin{equation}
\sqrt{\frac{r_1^2+r_2^2-1-\sqrt{(r_1^2-r_2^2)^2+1}}{2}}.
\end{equation}

\end{itemize}

The conjecture is that these constructions generate all spectral boundaries of $\vb{M}$.

