			\cite{krieger_slow_2009};
			\item \label{nw:d=4}
            For any $\nu>1$, there exists $\phi$ solving \cref{in:eq:nonlin} with $d=4$, $p=3$ s.t.~$\phi|_{\C}=\O(r^{\nu-2})$ and s.t.~$\phi$ is $C^{\frac{\nu}{2}-}$ across $\C$ with infinite conormal regularity \cite{samuelian_construction_2024};
			\item \label{wm:d=2_poly} 
            For any $\nu\in\N_{\geq 2}$, there exists
        $\phi$ solving \cref{in:eq:wave_map_k} with $d=2$ and $k=1$ s.t.~$\phi|_{\C}=\O(r^{\nu})$  and is smooth across  $\C$ \cite{jeong_quantized_2025};\footnote{We ignored extra logarithmic factors appearing, as the upper bounds suffices for the discussion here}
			\item \label{wm:d=2_log}
            There exists $\phi$ solving \cref{in:eq:wave_map_k} with $d=2$ and $k=1$ s.t.~$\phi|_{\C}=\O\big(e^{-\sqrt{|\log(r)|}}\big)$ and s.t.~$\phi$ is smooth across $\C$ \cite{raphael_stable_2012,kim_sharp_2023};
            \item \label{wm:d=2_log_k}
            There exists $\phi$ solving \cref{in:eq:wave_map_k} with $d=2$ and $k\geq2$ s.t.~$\phi|_{\C}=\O\big(|\log(r)|^{\frac{-1}{2k-2}} \big)$ and s.t.~$\phi$ is smooth across $\C$ \cite{raphael_stable_2012}; 
			\item  \label{nw:d=4_log}
            There exists $\phi$ solving \cref{in:eq:nonlin} with $d=4$, $p=3$, $\phi|_{\C}=\O(r^{-1}e^{-\sqrt{|\log(r)|}+O(1)})$ and s.t.~$\phi$ is smooth across $\C$ \cite{hillairet_smooth_2012}.
		\end{enumerate}
		The solutions above are smooth in the interior of $\C$, i.e.~for $v<0$.
        Moreover, their scale critical norm on $\{t=-\tau,\abs{r}\leq \tau\}$ remains bounded away from 0 as $\tau\to0$.

        Finally, in all statements, smoothness can be replaced by $C^k$, infinite conormal regularity across $\C$ can be replaced by conormal regularity of degree $k$, and the notation $\mathcal{O}(\dots)$ introduced below \cref{in:conj:type1} can be replaced by $\mathcal{O}_{k}(\dots)$. We then refer to the conjectured solutions as "$k$-regular solutions".

