Let \(g, r, d, k\) be such that \(g-d+r \geq 0\) and \(0 \leq \rho(g, r, d) < r-2\) and \(k \geq 2\).  Let \(C\) be a general curve of genus \(g\).  Then the locus of line bundles \(L \in W^r_dC\) for which \(\phi^k_L\) is not of maximal rank has dimension
\begin{equation}\label{eq:smrc_dim}
\rho(g, r, d) - 1  - \left| {r + k \choose k} - (dk+1 - g) \right|.
\end{equation}
In particular,  \(\phi^k_L\) is of maximal rank for \textit{every} \(L \in W^r_dC\) when this quantity is negative.

\label{conj:Coursym}
	Let $H \in \Omega_{\rm cl}^{n+1}(M)$ be the field strength of the $(n{-}1)$-gerbe connection $\CA$.
	There is a canonical equivalence
	\begin{equation}
		\mathrm{Cour}_{n-1}(H) \weq \sym^{\leqslant n-1} (g, \CA)
	\end{equation}
	of $L_\infty$-algebras over $TM$.

\label{conj:CourAtsym}
There is a commutative diagram of $L_\infty$-algebras over $TM$
\begin{equation}
\begin{tikzcd}[row sep = 1cm]
\mathrm{Cour}_{n-1}(H) \ar[d] \ar[r] & \sym^{\leqslant n-1}(g,\CA) \ar[d] \\
\At_{n-1}(H) \ar[r] & \cC\At(g)
\end{tikzcd}
\end{equation}
where the top horizontal arrow is the weak equivalence of Conjecture~\ref{conj:Coursym}, the bottom horizontal arrow is induced by the $\infty$-equivalence from Theorem~\ref{st:strictification of At(CG)}, the left vertical arrow is the canonical $\infty$-projection of Theorem~\ref{prop:Linftyproj}, and the right vertical arrow is induced from the composition of the weak equivalence from Remark~\ref{rem:symgCAt} with the chain of morphisms in \eqref{eq:symchain}.

\label{conj:hetSuGra}
	Let $\Hom_v(M, \rmB^2\, \rmB_\nabla \rmU(1))$ and $\Hom_v(M, \rmB \String_{\rm CS}(K))$ denote the full substacks of the respective internal homs where all the 1-forms induced via pullback by the connective structure of the multiplicative gerbe on $K$ are \textit{vertical}, i.e.~they only have form legs along $M$ (compare Example~\ref{ex:vertical forms def thy}).
	Then:
	\begin{myenumerate}
		\item The stacks $\Hom_v(M, \rmB^2\, \rmB_\nabla \rmU(1))/\cDiff(M)$ and $\Hom_v(M, \rmB \String_{\rm CS}(K))/\cDiff(M)$ have (possibly quasi-coherent) deformation theory.

		\item A lift of $P_K:M \longrightarrow \rmB K$ to $\rmB \String_{\rm CS}(K)$ exists if and only if a lift to $\rmB \String(K)$ exists.

		\item The $L_\infty$-algebra $T\big(* /\, (\Hom_v(M, \rmB \String_{\rm CS}(K))/\cDiff(M))\big)$ has a canonical map to the Lie algebra $TM$, and a $C^\infty(M)$-linear splitting of this map (as dg $C^\infty(M)$-modules) is the same as a geometric string structure on $P_K$ together with a symmetric 2-tensor $\gamma \in \Gamma(M, \midvee^2\, T^*M)$.
	\end{myenumerate}

