\label{conj:WeylLaw}
    Let $u_0$ be an admissible initial condition according to Definition \ref{def:AdmisInitCond} and let $R^\wyl: [1/2\delta, \zeta_\maxrm]_{\mathcal{Q}_\delta} \to \R_+$ be defined by
    \begin{equation}
        R^\wyl(\zeta) := \frac{1}{4 \delta} \int_{x_-(\zeta)}^{x_+(\zeta)} W_{0}\left(-2 \delta \zeta \ee^{-2\delta(\zeta + u_0(x))} \right) - W_{-1}\left(-2 \delta \zeta \ee^{-2\delta(\zeta + u_0(x))}\right) \, \dd x \, .
        \label{eq:RWeylLawDef}
    \end{equation}
    where $x_\pm : (1/2\delta, \zeta_\maxrm]_{\quadratrix{\delta}} \to \R$ are the turning point functions defined implicitly by
    \begin{equation}
        u_0(x_\pm(\zeta)) = E(\zeta) 
        \label{eq:TurningPointFunctDef}
    \end{equation}
    with $E$ as in \eqref{eq:TurningPointFromELevel} and such that $x_-(\zeta) \leq x_\maxrm \leq x_+(\zeta)$.
    Additionally, $W_n$ for $n \in \Z$ are the standard branches of the Lambert-$W$ function \cite[Equation 4.13.1\_1]{DLMF}.
    The asymptotics of the eigenvalues satisfy the ``ILW Weyl law''
    \begin{equation}
        R^\wyl(\zeta_n) = \left( n - \frac{1}{2} \right) \pi \epsilon + \bigO{\epsilon^2}
        \label{eq:WeylLaw}
    \end{equation}
    for $n \in \N$.
    Defining the tail integrals $\theta_\pm: [1/2\delta, \ \zeta_{\maxrm}]_{\quadratrix{\delta}} \to \R$
    \begin{equation}
        \theta_\pm(\zeta) := \im{\zeta} x_\pm(\zeta) + \int^{\pm\infty}_{x_\pm(\zeta)} \im{ \zeta + \frac{1}{2 \delta} W_{-1}\left(-2\delta \zeta \ee^{-2\delta(\zeta + u_0(x))}\right)} \, \dd x \, .
        \label{eq:TailIntegralsDef}
    \end{equation}
    Then the norming constants have the asymptotics
    \begin{align}
        c_n &= \exp \Bigg( \frac{2}{\epsilon} \theta_+(\zeta_n) \Bigg) \left| \frac{(2 \delta)^2 \zeta_n}{1 -2 \delta \zeta_n} \right| \nonumber \\
        &\Quad[2] \times \left( \int_{x_-(\zeta_n)}^{x_+(\zeta_n)} \frac{2\delta W_{-1}(-2\delta \zeta_n \ee^{-2\delta(\zeta_n + u_0(x))})}{1+W_{-1}(-2\delta \zeta_n \ee^{-2\delta(\zeta_n + u_0(x))})} - \frac{2\delta W_0(-2\delta \zeta_n \ee^{-2\delta(\zeta_n + u_0(x))})}{1+W_0(-2\delta \zeta_n \ee^{-2\delta(\zeta_n + u_0(x))})} \, \dd x \right)^{-1} \nonumber \\
        &\Quad[2] \times \left( 1 + \bigO{\epsilon^{1/6}} \right) \, . \label{eq:NormingConstAsymptoticFormula}
    \end{align}
    Finally, the reflection coefficient is small beyond all orders in $\epsilon$.

\label{conj:main}
The constant $8/\pi^2$ admits the following GCF representation:
\begin{equation}\label{eq:conjecture}
\frac{8}{\pi^2} = 1 - \cfrac{2 \cdot 1^4 - 1^3}{7 - \cfrac{2 \cdot 2^4 - 2^3}{19 - \cfrac{2 \cdot 3^4 - 3^3}{37 - \dots}}}
\end{equation}
where the partial denominators are $b_n = 3n^2+3n+1$ and partial numerators are $a_n = -(2n^4-n^3)$.

There exists an inextendible spacelike hypersurface $\Sigma\subset\R^{n+1}$ and finite energy smooth Cauchy data $(\phi_0,\phi_1)\in H^1(\R^n)\times L^2(\R^n) \cap C^{\infty}(\R^n) \times C^{\infty}(\R^n)$ such that the solution to
	\begin{equation}\label{in:eq:ivp}
		P[\phi]=0,\qquad (\phi|_{t=0},\partial_t\phi|_{t=0})=(\phi_0,\phi_1)
	\end{equation}
	forms an ODE type singularity along all of $\Sigma$.

There exists a smooth\footnote{By smoothness, we mean this family is both smooth in the spatial variable $x \in \R^n$ and with respect to the interpolating parameter $\omega$. We will put the initial data at $t = 1$ in analogy the setup of \cref{in:thm:main2}, where the singularity is near $t = 0$.} one-parameter family $(\phi_{0, \omega}, \phi_{1, \omega})$ with $\omega \in [0, 1]$, serving as initial data for the nonlinear wave $P[\phi] = 0$ with $p = 3$ and $n \geq 5$ in the sense $(\phi|_{t = 1}, \partial_t \phi|_{t = 1}) = (\phi_{0, \omega}, \phi_{1, \omega})$, such that the following hold, for some $\omega^* \in (0, 1)$:
    \begin{enumerate}
        \item We have $(\phi_{0,0}, \phi_{1, 0}) = (0, 0)$ and, for $0 \leq \omega < \omega^*$, the corresponding solution exists globally in time to the past.

        \item We have $(\phi_{0, 1}, \phi_{1, 1}) \equiv (c_3, - \alpha_3 c_3)$, at least in some sufficiently large ball and, for $\omega^* < \omega \leq 1$, the corresponding solution to $P[\phi] = 0$ blows up to the past, and some portion of the past boundary of the maximal domain of existence is a smooth spacelike hypersurface $\Sigma^-_{\omega}$ along which the solution exhibits ODE-type blow up.

        \item At the threshold $\omega = \omega^*$, the past development of the data $(\phi_{0, \omega^*}, \phi_{1, \omega^*})$ blows up at the point $(t, x) = (0, 0)$, and, within the future light cone of this point, the solution approaches the nontrivial self-similar solution \eqref{in:eq:self_similar} as $t \downarrow 0$. The solution should exhibit locally naked singularity formation.
    \end{enumerate}

\label{conj:main}
    Let \(G\) be a graph and write $d_v\defeq \deg_G(v)$. Then for any antiferromagnetic edge-weighted graph $H$,
    \begin{equation}\label{eq:afm}
        \hom(G,H)\geq \prod_{v\in V(G)}\hom(K_{d_v+1},H)^{\frac{1}{d_v+1}}.
    \end{equation}

\label{conj:QCYBE trans 1,-1}
Let~$R$ be any solution of QYBE. Then
for any transitive $n\times n$-matrix $\boldsymbol{\epsilon}=(\epsilon_{i,j})_{1\le i,j\le n}$ with~$\epsilon_{i,j}\in\{1,-1\}$, $1\le i,j\le n$,
\begin{equation}\label{eq:R eps defn}
\mathbf R^{(\boldsymbol{\epsilon})}:=
(R_{1,2n}^{(\epsilon_{n,1})}\cdots 
R_{n,2n}^{(\epsilon_{n,n})}) 
(R_{1,2n-1}^{(\epsilon_{n-1,1})}\cdots 
R_{n,2n-1}^{(\epsilon_{n-1,n})})
\cdots (R_{1,n+1}^{(\epsilon_{1,1})}\cdots R_{n,n+1}^{(\epsilon_{1,n})})
\end{equation}
solves QYBE.

\label{conj:K n n-2}
$\tstirling{\vec K_n}{n-2}=(n-2)\binom{2n-3}n+\binom{2(n-2)}n$
for all~$n\ge 3$.

{\label{conj-low-deg}}
    For ``natural'' high-dimensional hypothesis testing problems between $\Pb$ and $\Qb$, the following statements hold.
    \begin{enumerate}
        \item[(1)] If $\mathsf{Adv}_{\leq D}(\Pb\|\Qb)=O(1)$ as $n\to\infty$, then there exists a constant $C$ such that no algorithm with running time $N^{D/(\log N)^C}$ that achieves strong detection between $\Pb$ and $\Qb$. 
        \item[(2)] If $\mathsf{Adv}_{\leq D}(\Pb\|\Qb)=1+o(1)$ as $n\to\infty$, then there exists a constant $C$ such that no algorithm with running time $N^{D/(\log N)^C}$ that achieves weak detection between $\Pb$ and $\Qb$. 
    \end{enumerate}

